INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (352,165,'assistant','According to Article 10 of \"Attendance and Leave Management Measures of Northline Industrial Systems Inc.\": \"Sick leave\"\n\n- Sick leave is subject to the provision of sick leave and registered records for level II and above hospitals;\n- If the total sick leave within the year does not exceed 10 days, it is paid at 80% of the basic salary;\n- For days exceeding 10, it is paid at 80% of the local minimum wage standard.','What is the method for calculating sick leave pay?','{\"id\": 3, \"name\": \"Full - Hybrid search with reranking and rewriting\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 10, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 10, \"rrf_k\": 60, \"rerank_enabled\": \"Yes\", \"rerank_model_id\": 3, \"rerank_top_n\": 4, \"query_rewrite_enabled\": \"Yes\", \"rewrite_type\": \"Multi-query expansion\", \"multi_query_count\": 3, \"parent_recall_enabled\": \"Yes\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"All capabilities enabled, for comparison with the previous two strategies.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'Answered',NULL,4580,'2026-09-04 03:41:43');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (353,166,'user','How do I resolve error ERR-5021 on the device?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 03:41:48');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (354,166,'assistant','ERR-5021 indicates incompatibility between point configuration and the protocol stack, commonly occurring after cross-major version firmware upgrades. The solution is to roll back to the firmware version before the upgrade, and follow the instructions in the [Firmware Upgrade and Version Release Notes] to first upgrade to the transitional version before the target version.',NULL,NULL,49,NULL,NULL,'Answered',NULL,3096,'2026-09-04 03:41:48');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (355,167,'user','How long is the GTE-3000 warranty?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04 03:42:50');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (356,167,'assistant','The warranty period for GTE-3000 is 24 months from the date of manufacture.  \n(According to Document 5, Article 2, Paragraph 1: \"The warranty period for GTE-3000, GTE-3000S, and GTE-3000Pro is 24 months from the date of manufacture\")','How long is the GTE-3000 warranty?','{\"id\": 2, \"name\": \"Advanced - Hybrid search\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 8, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 8, \"rrf_k\": 60, \"rerank_enabled\": \"No\", \"rerank_model_id\": null, \"rerank_top_n\": 3, \"query_rewrite_enabled\": \"No\", \"rewrite_type\": null, \"multi_query_count\": 3, \"parent_recall_enabled\": \"No\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"Vector plus BM25 dual-path retrieval followed by RRF fusion, to solve the problem of retrieving proper nouns.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'Answered',NULL,3040,'2026-09-04 03:42:50');
