INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (362,171,'assistant','No relevant clauses were found in the current system. Please contact the Human Resources Department for confirmation.','How to process a refund?','{\"id\": 3, \"name\": \"Full - Hybrid search with reranking and rewriting\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 10, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 10, \"rrf_k\": 60, \"rerank_enabled\": \"Yes\", \"rerank_model_id\": 3, \"rerank_top_n\": 4, \"query_rewrite_enabled\": \"Yes\", \"rewrite_type\": \"Multi-query expansion\", \"multi_query_count\": 3, \"parent_recall_enabled\": \"Yes\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"All capabilities enabled, for comparison with the previous two strategies.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'No retrieval',NULL,4347,'2026-09-05 15:10:59');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (363,172,'user','How does your refund process work?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 15:11:50');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (364,172,'assistant','According to the documents, the refund process is as follows:\n\n1. We complete the appearance and function inspection within 3 working days after receiving the goods;  \n2. Refund is processed within 5 working days after the inspection passes, and the refund is returned via the original route.  \n\nIn addition, please note:  \n- (b) The equipment was detected to have been artificially damaged, the return application cancelled, the equipment sent back to the customer and the cost of freight borne by the client;  \n- If a value-added tax special invoice has been issued, the original invoice must be returned (or if it has been certified and offset, the customer must issue a red invoice information form), and the refund will be processed only after we receive the original invoice.',NULL,NULL,53,NULL,NULL,'Answered',NULL,4142,'2026-09-05 15:11:50');
