INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (366,173,'assistant','The GTE-3000Pro supports up to 20000 acquisition points.','What is the maximum number of data points supported by the GTE-3000Pro?','{\"id\": 2, \"name\": \"Advanced - Hybrid search\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 8, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 8, \"rrf_k\": 60, \"rerank_enabled\": \"No\", \"rerank_model_id\": null, \"rerank_top_n\": 3, \"query_rewrite_enabled\": \"No\", \"rewrite_type\": null, \"multi_query_count\": 3, \"parent_recall_enabled\": \"No\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"Vector plus BM25 dual-path retrieval followed by RRF fusion, to solve the problem of retrieving proper nouns.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'Answered',NULL,1612,'2026-09-05 15:14:06');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (367,174,'user','How long is the warranty?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 15:14:57');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (368,174,'assistant','The documents do not explicitly state the specific duration of the warranty period for the entire equipment (e.g., 12 months, 24 months), but only specify the method of calculating the warranty period and the warranty period for accessories and spare parts:\n\n- The warranty period is based on the manufacturing date indicated on the equipment nameplate;  \n- If the customer can provide a valid purchase receipt, the warranty period can start from the purchase date, with a maximum extension of 3 months;  \n- The warranty period for accessories such as power adapters, antennas, terminals, and rail clips is 12 months;  \n- Spare parts purchased separately have a 6-month warranty;  \n- Spare parts replaced during whole machine repair follow the remaining warranty period of the whole machine (if less than 3 months, it is counted as 3 months).\n\nHowever, the length of the warranty period for the entire equipment itself (e.g., standard of how many months or years) is not specified in the provided documents.\n\nTherefore, the answer is: No relevant information was found in the knowledge base.',NULL,NULL,54,NULL,NULL,'Answered',NULL,5675,'2026-09-05 15:14:57');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (453,215,'user','How does your refund process work?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 15:49:25');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (454,215,'assistant','According to the documents, the refund process is as follows:\n\n1. We complete the appearance and function inspection within 3 working days after receiving the goods;  \n2. Refund is processed within 5 working days after the inspection passes, and the refund is returned via the original route.  \n\nSupplementary explanation:  \n- If the equipment is detected to have been damaged by humans, the return request is cancelled and the equipment is sent back to the customer, who bears the cost of transportation;  \n- If a value-added tax special invoice has been issued, the original invoice must be returned (or if it has been certified and offset, the customer must issue a red invoice information form), and the refund will be processed only after we receive the original invoice.  \n\nThe above content is compiled based on the provided documents, with no additional inference.',NULL,NULL,67,NULL,NULL,'Answered',NULL,4540,'2026-09-05 15:49:25');
