INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (502,239,'assistant','The GTE-3000Pro can be configured with up to 20000 acquisition points.','How many data points does the GTE-3000Pro support?','{\"id\": 2, \"name\": \"Advanced - Hybrid search\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 8, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 8, \"rrf_k\": 60, \"rerank_enabled\": \"No\", \"rerank_model_id\": null, \"rerank_top_n\": 3, \"query_rewrite_enabled\": \"No\", \"rewrite_type\": null, \"multi_query_count\": 3, \"parent_recall_enabled\": \"No\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"Vector plus BM25 dual-path retrieval followed by RRF fusion, to solve the problem of retrieving proper nouns.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'Answered',NULL,3269,'2026-09-05 16:27:09');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (503,240,'user','How are after-sales refunds usually processed?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 16:31:59');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (504,240,'assistant','According to the documents, the after-sales refund process is as follows:\n\n1. We complete the appearance and function inspection within 3 working days after receiving the goods;  \n2. Refund is processed within 5 working days after the inspection passes, and the refund is returned via the original route.  \n\nIn addition, if an artificial damage to the equipment is detected and a return request is cancelled, the equipment is sent back to the customer, who bears the cost of transportation.\n\nNote: The applicable scenarios for refund must comply with the return policy (e.g., confirming the equipment itself has quality issues and cannot be repaired within 15 days of delivery), please refer to the terms of refundable and non-refundable situations.',NULL,NULL,74,NULL,NULL,'Answered',NULL,6299,'2026-09-05 16:31:59');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (505,241,'user','List the differences between the GTE-3000, GTE-3000S, and GTE-3000Pro, including processor, memory, interfaces, wireless connectivity, and data point limits.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 16:34:36');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (506,241,'assistant','According to the documentation, the differences between the three models, GTE-3000, GTE-3000S, and GTE-3000Pro, are as follows:\n\n| Item | GTE-3000 | GTE-3000S | GTE-3000Pro |\n|------|----------|-----------|-------------|\n| **Processor** | Quad-core 1.2GHz | Quad-core 1.2GHz | Octa-core 1.8GHz |\n| **Memory** | 2GB | 4GB | 8GB |\n| **Storage** | 8GB eMMC | 16GB eMMC | 64GB eMMC |\n| **Ethernet Port** | 2 × Gigabit | 4 × Gigabit | 4 × Gigabit |\n| **Serial Port** | 2 × RS485 | 4 × RS485/RS232 | 4 × RS485/RS232 |\n| **Wireless Capability** | None | 4G Full Network | 5G + Wi-Fi 6 |\n| **Point Limit** | 2000 points | 5000 points | 20000 points |\n| **Digital I/O** | Not mentioned (not specified in the documentation) | Not mentioned (not specified in the documentation) | 4 channels DI (dry contact input), 2 channels DO (relay output, 30VDC/2A) |\n| **CNC Protocol Support (FOCAS)** | Not supported (the documentation clearly states that only GTE-3000Pro supports it) | Not supported | Supported |\n| **Edge Inference Capability** | None | None | Has local inference capability, can run lightweight vision detection models |\n\nNote:  \n- Serial port types and quantities are based on the table in [Document 1] and the description in [Document 3] about \"GTE-3000S and GTE-3000Pro\'s... RS485/RS232\"; GTE-3000 is only labeled as \"2 × RS485\" and does not mention RS232, so RS232 is not included.  \n- DI/DO are only explicitly mentioned as unique features of GTE-3000Pro in [Document 3] and [Document 5]; other models are not mentioned, so they are treated as \"not mentioned\" (no inference is made).  \n- Point limit data comes from [Document 5]: \"A GTE-3000 can be configured with up to 2000 acquisition points, GTE-3000S with 5000, and GTE-3000Pro with 20000.\"  \n- Support for the FOCAS protocol is explicitly limited to \"only GTE-3000Pro\" ([Document 4]).  \n- Description of edge inference capability is referenced from the last sentence of [Document 1].','List the differences between the GTE-3000, GTE-3000S, and GTE-3000Pro, including processor, memory, interfaces, wireless connectivity, and data point limits.','{\"id\": 2, \"name\": \"Advanced - Hybrid search\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 8, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 8, \"rrf_k\": 60, \"rerank_enabled\": \"No\", \"rerank_model_id\": null, \"rerank_top_n\": 3, \"query_rewrite_enabled\": \"No\", \"rewrite_type\": null, \"multi_query_count\": 3, \"parent_recall_enabled\": \"No\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"Vector plus BM25 dual-path retrieval followed by RRF fusion, to solve the problem of retrieving proper nouns.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'Answered',NULL,15640,'2026-09-05 16:34:36');
