INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (560,270,'assistant','ERR-5021 indicates incompatibility between point configuration and the protocol stack, commonly occurring after cross-major version firmware upgrades. The solution is to roll back to the firmware version before the upgrade, and follow the instructions in the [Firmware Upgrade and Version Release Notes] to first upgrade to the transitional version before the target version.',NULL,NULL,84,NULL,NULL,'Answered',NULL,4418,'2026-09-05 17:27:44');
