INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (607,293,'user','How are after-sales refunds processed?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 17:41:33');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (608,293,'assistant','According to the documents, the after-sales refund process is as follows:\n\n1. We Complete the Appearance and Functionality Inspection Within 3 Working Days After Delivery;  \n2. Refund Processing Within 5 Working Days After Inspection Pass, Refund Returned via Original Route.\n\nAdditionally, Supplementary Explanation:\n- If the equipment is detected to have been damaged by humans, the return request is cancelled and the equipment is sent back to the customer, who bears the cost of transportation;  \n- For Returns Due to Equipment Quality Issues (Within 15 Days of Delivery, Confirmed by Inspection and Unrepairable), Round-trip Freight Is Covered by the Company, Full Refund of Payment;  \n- For Unconditional Returns (Within 7 Days of Delivery, Unopened Etc. Conditions Met), Customer Bears Round-trip Freight, Company Does Not Charge Depreciation Fee, Full Refund of Payment.\n\nOther Scenarios (Such as Model/Configuration Mismatch and Customer Not Accepting Replacement) Also Support Returns, All Costs Covered by the Company (See Document 2).\n\nNote: Non-returnable Scenarios (Such as Over 15 Days, Used with Wear, Broken Seal, Self-disassembly, Custom Equipment, Trial to Purchase, Promotional/Clearance/Sample Discounted Equipment Etc.) Do Not Apply for Refund (See Document 3).',NULL,NULL,93,NULL,NULL,'Answered',NULL,8221,'2026-09-05 17:41:33');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (609,294,'user','What company policies are available?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 17:42:04');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (610,294,'assistant','No relevant clauses were found in the current system. Please contact the Human Resources Department for confirmation.','What is your organization\'s internal system?','{\"id\": 3, \"name\": \"Full - Hybrid search with reranking and rewriting\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 10, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 10, \"rrf_k\": 60, \"rerank_enabled\": \"Yes\", \"rerank_model_id\": 3, \"rerank_top_n\": 4, \"query_rewrite_enabled\": \"Yes\", \"rewrite_type\": \"Multi-query expansion\", \"multi_query_count\": 3, \"parent_recall_enabled\": \"Yes\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"All capabilities enabled, for comparison with the previous two strategies.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'No retrieval',NULL,4278,'2026-09-05 17:42:04');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (611,295,'user','How do I claim travel expenses?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 17:42:43');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (612,295,'assistant','According to the \"Northline Industrial Systems Inc. Travel and Expense Reimbursement Management System\" (GL-FIN-2024-004, V3.5), the reimbursement process and requirements for travel expenses are as follows:\n\nOne, **Prerequisites**  \n- It must follow the \"approval before expenditure\" principle: before traveling, an official travel application must be submitted via the OA system, specifying the purpose, destination, start and end dates, accompanying personnel, and estimated expenses; approval must be obtained before booking tickets; for urgent travel, the application must be submitted within one working day after departure (third clause).  \n- Expenses incurred without approval may be refused by the company (second clause).\n\nTwo, **Reimbursement Timeline**  \n- Reimbursement forms must be submitted within 30 days after the expense occurs; cross-year expenses must be submitted by January 15th of the following year at the latest, and will not be accepted after the deadline (eighth clause).\n\nThree, **Document Requirements**  \n- The invoice header must be the company\'s full name, and the taxpayer identification number must be accurate;  \n- VAT special invoices must be authenticated within 360 days from the date of issuance;  \n- Meal and accommodation expenses must be accompanied by consumption details;  \n- Taxi fares must provide a trip itinerary (not only payment screenshots) (ninth clause).\n\nFour, **Expense Standards and Special Provisions**  \n- **Transportation**: executed according to the standard for each position level (see the attached table in the system), for example, ordinary employees may apply for upgraded cabins if a single flight exceeds 3 hours or a train exceeds 6 hours, but must be approved by the vice president in charge (fifth clause, attached table);  \n- **Accommodation**: there is a clear upper limit per person per night; expenses exceeding the standard must be applied for in advance and the reason explained, and after the fact, the reimbursement will be based on the standard upper limit, with the difference borne by the individual; two employees of the same gender sharing a standard room will receive a subsidy of 50 CAD per person per night for the savings (sixth clause);  \n- **Travel Allowance**: issued per person per day; no allowance is given if the travel is less than 8 hours on the same day; if meals are arranged by the client or partner, the allowance for that meal will not be issued; if an employee is continuously stationed at the client\'s site for 5 working days, an additional site allowance will be issued according to Article 17 of the Employee Handbook (seventh clause).\n\nFive, **Approval and Payment**  \n- Reimbursement approval authority is executed according to the tenth clause of the system (the specific authority details are not listed in the original text, so they are not provided in the knowledge base);  \n- Fixed payment dates are on the 10th and 25th of each month; reimbursement forms must be completed by the finance department three working days before the payment date, otherwise they will be postponed to the next period (eleventh clause).\n\nSix, **Other Important Provisions**  \n- The loan must be settled within 10 working days after the trip; if the previous loan has not been settled, a new loan cannot be issued (twelfth clause);  \n- Falsifying invoices, false expense reporting, or splitting documents to bypass approval will result in full reimbursement and will be treated as a serious disciplinary offense (thirteenth clause).\n\nIf specific standard amounts for different positions (such as accommodation standards or travel allowances) are needed, the knowledge base does not provide detailed numerical values.','What are the reimbursement regulations and operational steps for travel-related expenses?','{\"id\": 3, \"name\": \"Full - Hybrid search with reranking and rewriting\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 10, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 10, \"rrf_k\": 60, \"rerank_enabled\": \"Yes\", \"rerank_model_id\": 3, \"rerank_top_n\": 4, \"query_rewrite_enabled\": \"Yes\", \"rewrite_type\": \"Multi-query expansion\", \"multi_query_count\": 3, \"parent_recall_enabled\": \"Yes\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"All capabilities enabled, for comparison with the previous two strategies.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'Answered',NULL,13930,'2026-09-05 17:42:43');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (613,296,'user','How do I install the GTE-3000?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 17:43:35');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (614,296,'assistant','According to the materials, the installation method of GTE-3000 is as follows:\n\n1. **Installation Method**: supports two installation methods: DIN rail installation and wall mounting (see material 2).\n\n2. **DIN Rail Installation**:  \n   - Disconnect the on-site power supply, confirm that the power indicator light is off before proceeding with the wiring work (material 1);  \n   - Align the gateway\'s snap hook with the DIN rail, first hang the side and then push down to secure, and you can hear the snap hook in place (material 1).\n\n3. **Wall Mounting**: use M4 screws to fix the four corners (material 1).\n\n4. **Power Connection**:  \n   - Use a 3-pin terminal (V+, V-, PE), PE must be connected to the cabinet grounding bar, and the grounding resistance must not exceed 4Ω (material 1);  \n   - Power supply requirements are DC 9V to 36V, with an independent circuit breaker reserved (Document 1);  \n   - Before installation, confirm that the ambient temperature does not exceed 60°C long-term, and it is away from strong interference sources such as inverters and high-power contactors (Document 1).\n\n5. **Network Access**:  \n   - LAN1 is the management port, LAN2 is the business port; after making the Ethernet cable, use a tester to confirm the wiring sequence is T568B (Document 7);  \n   - Wired access requires pre-installed Ethernet cables (Document 1).\n\n6. **Power On and Status Confirmation**:  \n   - After power on, observe the indicator lights: PWR steady on indicates normal power supply, SYS flashing once per second indicates normal system operation (Document 7).\n\nNote: Before installation, three confirmations must be completed (ambient temperature, power supply, network conditions), see Document 1.','How do I install the GTE-3000?','{\"id\": 2, \"name\": \"Advanced - Hybrid search\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 8, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 8, \"rrf_k\": 60, \"rerank_enabled\": \"No\", \"rerank_model_id\": null, \"rerank_top_n\": 3, \"query_rewrite_enabled\": \"No\", \"rewrite_type\": null, \"multi_query_count\": 3, \"parent_recall_enabled\": \"No\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"Vector plus BM25 dual-path retrieval followed by RRF fusion, to solve the problem of retrieving proper nouns.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'Answered',NULL,6604,'2026-09-05 17:43:35');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (615,297,'user','How do I install the GTE-3000?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 17:44:30');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (616,297,'assistant','According to the documents, the installation method for GTE-3000 is as follows (applicable to the full series of GTE-3000 / GTE-3000S / GTE-3000Pro):\n\n1. **Pre-Installation Confirmation**:  \n   - The ambient temperature at the installation location does not exceed 60°C long-term, and it is away from strong interference sources such as inverters and high-power contactors;  \n   - On-site power supply is DC 9V to 36V, with an independent circuit breaker reserved;  \n   - Network conditions are met: wired access requires pre-installed Ethernet cables; 4G/5G access requires on-site signal strength no less than -95dBm.\n\n2. **Installation Methods** (support two types):  \n   - **DIN Rail Installation**: Align the gateway\'s snap hook with the DIN rail, first hang the side then push down to secure, you can hear the snap hook in place sound;  \n   - **Wall Mount Installation**: Use M4 screws to fix the four corners.\n\n3. **Wiring Requirements**:  \n   - Disconnect the on-site power supply, confirm the power indicator light is off before wiring;  \n   - Power connection: the 3-pin terminal from left to right is V+, V-, PE, PE must be connected to the grounding busbar of the cabinet, grounding resistance no more than 4Ω;  \n   - RS485 connection: A connects to A, B connects to B, 120Ω terminal resistor is enabled at both ends of the bus, shield layer single-ended grounding.\n\n4. **Ethernet Connection**:  \n   - LAN1 is the management port, LAN2 is the business port;  \n   - The wiring sequence must be T568B, it is recommended to use a tester to confirm.\n\n5. **Power On and Status Confirmation**:  \n   - After power on, observe the indicator lights: PWR steady on indicates normal power supply, SYS flashing once per second indicates normal system operation, COM flashing indicates data transmission and reception on the serial port.\n\nThe above content is compiled based on Documents 1, 2, and 7, with no additional external information added.','How do I install the GTE-3000?','{\"id\": 2, \"name\": \"Advanced - Hybrid search\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 8, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 8, \"rrf_k\": 60, \"rerank_enabled\": \"No\", \"rerank_model_id\": null, \"rerank_top_n\": 3, \"query_rewrite_enabled\": \"No\", \"rewrite_type\": null, \"multi_query_count\": 3, \"parent_recall_enabled\": \"No\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"Vector plus BM25 dual-path retrieval followed by RRF fusion, to solve the problem of retrieving proper nouns.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'Answered',NULL,7733,'2026-09-05 17:44:30');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (617,298,'user','How do I claim travel expenses?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-05 17:44:51');
INSERT INTO `chat_message` (`id`, `session_id`, `role`, `content`, `rewritten_query`, `strategy_snapshot`, `agent_run_id`, `prompt_tokens`, `completion_tokens`, `finish_reason`, `error_message`, `cost_millis`, `create_time`) VALUES (618,298,'assistant','According to the \"Northline Industrial Systems Inc. Travel and Expense Reimbursement Management System\" (Document Number: GL-FIN-2024-004, Version V3.5), the reimbursement process and requirements for travel expenses are as follows:\n\n1. **Prerequisites**: Must follow the \"approval first, expenditure later\" principle. Before traveling, submit a business trip application on the OA system (indicating the reason, destination, start and end dates, accompanying personnel, estimated expenses), and only after approval can tickets be booked; for urgent business trips, the application must be submitted within one working day after departure (Article 3).\n\n2. **Reimbursement Deadline**: Submit the reimbursement form within 30 days after the expense occurs; cross-year expenses must be submitted by January 15th of the following year, and will not be accepted after the deadline (Article 8).\n\n3. **Document Requirements**:\n   - The invoice header must be the company\'s full name, and the taxpayer identification number must be accurate;\n   - VAT special invoices must be authenticated within 360 days from the date of issuance;\n   - Meal and accommodation expenses must be accompanied by consumption details;\n   - Taxi fares must provide a trip itinerary (not only payment screenshots) (ninth clause).\n\n4. **Accommodation and Allowance Standards**:\n   - Accommodation is executed according to the level standard (the specific amount is not fully listed in the document, but it clearly states that \"exceeding the standard accommodation requires prior application and explanation of the reason\", and the excess amount is reimbursed at the standard upper limit, with the difference paid by the individual);\n   - Two employees of the same gender traveling together are encouraged to share a standard room to save costs; a subsidy of 50 CAD per person per night is provided (Article 6);\n   - Subsidies are issued according to the daily standard per person; no subsidy is given for round-trip trips lasting less than 8 hours on the same day; if meals are arranged by the client or partner, the corresponding meal subsidy is not issued; for employees who stay on-site continuously for 5 working days, an additional on-site subsidy is issued according to Article 17 of the Employee Handbook (Article 7).\n\n5. **Payment Schedule**: Fixed payment dates are on the 10th and 25th of each month; reimbursement forms completed with financial approval within 3 working days before the payment date are included in the current payment, otherwise they are postponed to the next period (Article 11).\n\n6. **Loan Reconciliation**: If a prepayment is involved, the single transaction shall not exceed 80% of the estimated expenses; reconciliation must be completed within 10 working days after the trip; no new loan can be made if the previous loan has not been reconciled (Article 12).\n\n7. **Approval Authority**: Approval is conducted according to the number of days and nature of the trip (e.g., trips within 3 days are approved by the department head, trips from 3 to 7 days by the vice president in charge, and trips over 7 days or overseas by the general manager); the reimbursement approval authority is specified in Article 10 of the regulations (the content is not expanded, but the existence of a tiered approval mechanism is clearly stated) (Article 4, Article 10).\n\n8. **Violation Handling**: For false invoicing, false expense reporting, or splitting documents to bypass approval, the full amount will be reclaimed and treated as a serious disciplinary violation according to Article 30 of the Employee Handbook (Article 13).\n\nIn summary, the reimbursement of travel expenses must strictly follow the full process management requirements of pre-approval, compliant invoices, timely submission, tiered review, and timely reconciliation.','What are the reimbursement regulations and procedures for travel expenses?','{\"id\": 3, \"name\": \"Full - Hybrid search with reranking and rewriting\", \"vector_enabled\": \"Yes\", \"vector_top_k\": 10, \"bm25_enabled\": \"Yes\", \"bm25_top_k\": 10, \"rrf_k\": 60, \"rerank_enabled\": \"Yes\", \"rerank_model_id\": 3, \"rerank_top_n\": 4, \"query_rewrite_enabled\": \"Yes\", \"rewrite_type\": \"Multi-query expansion\", \"multi_query_count\": 3, \"parent_recall_enabled\": \"Yes\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"No\", \"remark\": \"All capabilities enabled, for comparison with the previous two strategies.\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}',NULL,NULL,NULL,'Answered',NULL,14120,'2026-09-05 17:44:51');
