INSERT INTO `knowledge_base` (`id`, `name`, `description`, `embedding_model_id`, `chunk_strategy_id`, `document_count`, `chunk_count`, `status`, `create_user_id`, `create_time`, `update_time`) VALUES (208,'After-Sales Service Knowledge Base','Warranty terms, frequently asked questions, and spare parts and return policies for customer service agents and customers.',2,2,3,42,'Active',1,'2026-09-04 02:10:18','2026-09-04 12:32:54');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (153,206,125,NULL,0,'Standard chunk','# GTE-3000 Series Industrial Smart Gateway Technical Manual\n\nDocument Number: GL-PRD-2024-017\nVersion: V3.2\nModels covered: GTE-3000, GTE-3000S, and GTE-3000Pro\nPublished by the Product Department, Northline Industrial Systems Inc.\n\n## 1. Product Overview\n\nGTE-3000 Series is a industrial intelligent gateway launched by Northline Industrial Systems for discrete manufacturing and process industries. It is deployed between production line equipment and upper-level systems, responsible for protocol conversion, edge computing, and data cloud upload. The device adopts a fanless aluminum alloy casing design, supporting DIN rail mounting and wall mounting',655,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (154,206,125,NULL,1,'Standard chunk','.\n\nThere are three models in the series, with consistent hardware platforms, and differences mainly lie in computing power, number of interfaces, and wireless capabilities:\n\n| Model | Processor | Memory | Storage | Ethernet Port | Serial Port | Wireless | Typical Power Consumption |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| GTE-3000 | Quad-core 1.2GHz | 2GB | 8GB eMMC | 2 × Gigabit | 2 × RS485 | None | 6.5W |\n| GTE-3000S | Quad-core 1.2GHz | 4GB | 16GB eMMC | 4 × Gigabit | 4 × RS485/RS232 | 4G Full Network Coverage | 9.2W |\n| GTE-3000Pro | Eight-core 1.8GHz | 8GB | 64GB eMMC | 4 × Gigabit | 4 × RS485/RS232 | 5G + Wi-Fi 6 | 15.8W |\n\nGTE-3000 is the basic model, suitable for small-scale data collection on a single production line; GTE-3000S adds 4G uplink and more serial ports, suitable for workshops without wired networks; GTE-3000Pro has local inference capabilities, allowing lightweight vision detection models to run at the edge',953,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:39');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (155,206,125,NULL,2,'Standard chunk','.\n\n## 2. Environmental Parameters\n\n| Project | Metric |\n| --- | --- |\n| Operating Temperature | -20℃ ~ +70℃ |\n| Storage Temperature | -40℃ ~ +85℃ |\n| Relative Humidity | 5% ~ 95%, No Condensation |\n| Protection Level | IP40 (Can reach IP54 with dust cover kit) |\n| Input Voltage | DC 9V ~ 36V, Standard 24V Power Adapter |\n| Vibration Resistance | 5 ~ 500Hz,2Grms |\n| Mean Time Between Failures | MTBF ≥ 100000 Hours |\n\nWhen the installation site temperature is consistently higher than 60℃, a heat dissipation duct must be installed or the device must be moved out of the high-temperature area; otherwise, the processor will trigger frequency reduction protection, manifested as longer data collection cycles and increased data latency.\n\n## 3. Interface Description\n\n### 3.1 Power Interface\n\nThe left side of the device has a 3-pin Phoenix terminal, from left to right: V+, V-, PE. PE is the protective grounding; grounding is mandatory when there is significant electrical interference in the workshop, otherwise RS485 communication is prone to checksum errors.\n\n### 3.2 Ethernet Ports\n\nLAN1 is default as management port, with factory IP 192.168.1.10, subnet mask 255.255.255.0. LAN2 is default as business port, with factory configuration as DHCP client',1257,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:39');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (156,206,125,NULL,3,'Standard chunk','LAN2 is default as business port, with factory configuration as DHCP client. LAN3 and LAN4 of GTE-3000S and GTE-3000Pro can be configured as switch ports, cascading downstream devices\n\nWhen the management port IP is forgotten, hold the RESET button for more than 10 seconds to restore factory settings, returning the management port IP to 192.168.1.10. Restoring factory settings will clear all collected point configurations; make sure to export the configuration file before operation.\n\n### 3.3 Serial Ports\n\nRS485 uses a 2-pin terminal with A and B lines. Serial port parameters support 1200 ~ 115200bps, default 9600bps, 8 data bits, 1 stop bit, no parity check. A maximum of 32 slave devices can be connected on the same 485 bus, with 120Ω terminal resistors required at both ends of the bus. GTE-3000S and GTE-3000Pro have built-in terminal resistors that can be enabled via a dip switch.\n\n### 3.4 Digital Input/Output\n\nGTE-3000Pro provides 4 routes DI and 2 paths DO. DI is inputted for dry interfaces, which are relay output, contact capacity 30VDC/2A. DO is often used to connect sound alarms and to export signals when collecting breaks or threshold limits',1166,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (157,206,125,NULL,4,'Standard chunk','. DO is often used for connecting sound alarms to export signals when collecting breaks or thresholds.\n\n## 4. Protocol Support\n\nProtocols supported by the device facing field equipment:\n\n- Modbus RTU / Modbus TCP\n- OPC UA Client\n- Siemens S7(S7-200 Smart / S7-1200 / S7-1500)\n- Mitsubishi MC Protocol (3E Frame)\n- Omron FINS\n- Mitsubishi FX Series Programming Port Protocol\n- CNC Equipment\'s FOCAS Protocol (Only supported by GTE-3000Pro)\n\nProtocols supported by the device facing upper-level systems:\n\n- MQTT 3.1.1 / MQTT 5.0, supporting TLS encryption and mutual certificate authentication\n- HTTP / HTTPS Active Reporting\n- OPC UA Server\n- Standard access to AWS IoT and Azure IoT platforms\n\nGTE-3000 can be configured with up to 2000 data points, GTE-3000S with 5000, and GTE-3000Pro with 20000. New data points beyond the point limit will be rejected, and the web configuration page will prompt \"Number of data points exceeds the current model limit\"',954,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:40');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (158,206,125,NULL,5,'Standard chunk','New data points beyond the point limit will be rejected, and the web configuration page will prompt \"Number of data points exceeds the current model limit\"\n\n## 5. Data Collection and Reporting Mechanism\n\nCollection tasks are organized by \"Collection Groups.\" A collection group includes several data points, a collection cycle, and a reporting strategy. The minimum collection cycle is 100ms, maximum 3600s. Reporting strategies include three types:\n\n**Periodic Reporting**: Pack the latest value and report it at fixed intervals, independent of the collection cycle configuration. Suitable for trend data, such as temperature, current.\n\n**Change Reporting**: Report only when the value changes beyond the set deadband threshold. Suitable for state data, significantly reducing traffic. Deadband threshold supports absolute value and percentage formats.\n\n**Hybrid Reporting**: Immediately report upon change, while also reporting once at a longer heartbeat cycle to ensure the upper system receives the latest value even if it missed the change event. Recommended for production environments.\n\nData is stored in local cache when the network is down. GTE-3000 has a cache capacity of 100,000 entries, GTE-3000S has 500,000, and GTE-3000Pro has 5,000,000. After network recovery, data is resent in chronological order, with a default transmission rate limit of 200 entries per second to avoid overwhelming the upper system. When the cache is full, the oldest data is discarded on a first-in-first-out basis.\n\n## 6. Edge Computing\n\nGTE-3000Pro supports running edge rules and lightweight models on the device',1605,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (159,206,125,NULL,6,'Standard chunk','.\n\n## 6. Edge Computing\n\nGTE-3000Pro supports running edge rules and lightweight models on the device.\n\nEdge rules are written using a SQL-like syntax, for example:\n\n```text\nSELECT device_id, temperature\nFROM stream\nWHERE temperature > 85\n```\n\nAfter a rule is triggered, three types of actions can be initiated: reporting alarm messages, setting DO outputs, and calling write commands to downstream devices.\n\nModel inference supports ONNX format, with model files not exceeding 200MB. Typical scenarios include initial screening for product appearance defects, filtering out clearly qualified images at the edge to only upload suspected defective images to the central system for re-examination, reducing upward bandwidth usage by over 80%.\n\n## 7. Web Configuration Interface\n\nAccess `https://192.168.1.10` via browser, default account admin, default password Gl@2024. Password must be changed upon first login, with new password at least 10 characters, including at least three of the four categories: uppercase letters, lowercase letters, numbers, and special characters',1072,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:39');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (160,206,125,NULL,7,'Standard chunk','.\n\nMain functional areas:\n\n- Runtime Monitoring: CPU, memory, storage usage, real-time status of each collection group\n- Device Management: Adding, deleting, modifying, and querying field devices and data points, supporting Excel batch import\n- Data Forwarding: Configuration and topic mapping for northbound connections\n- Edge Rules: Rule writing and debugging\n- System Maintenance: Firmware upgrades, configuration import/export, log download, time synchronization\n\nExported configuration files are in an encrypted .glcfg format. During import, the model and version are validated, and cross-model imports are rejected. Configurations from GTE-3000 can be imported into GTE-3000S, but not vice versa, due to the possibility of exceeding the lower model\'s data point limit with higher model data points.\n\n## 8. Security Mechanism\n\nThe device defaults to disabling Telnet and FTP, only opening HTTPS and SSH. SSH default port is 22, which can be modified in the system maintenance page.\n\nSupports three levels of user roles: administrators can perform all operations; maintenance personnel can view monitoring, download logs, and restart collection tasks, but cannot modify point configuration; visitors have read-only access.\n\nFirmware packages are signed by Northline Industrial Systems, and signature verification is performed during device upgrades. If the signature is invalid, the upgrade is rejected and the original firmware is retained. The upgrade process takes about 3 to 5 minutes, during which data collection is interrupted. After upgrade, the device automatically restarts and restores the original configuration',1627,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:39');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (161,206,125,NULL,8,'Standard chunk','The upgrade process takes about 3 to 5 minutes, during which data collection is interrupted. After upgrade, the device automatically restarts and restores the original configuration\n\n## 9. Typical Deployment Methods\n\n**Single Machine Deployment**: One GTE-3000 connects to a PLC and instruments on a production line, and connects to the workshop switch via LAN2, with data reporting to the plant-level MES.\n\n**Dual Machine Hot Standby**: Two GTE-3000S units are interconnected via a heartbeat line. The standby unit takes over within 5 seconds if the main unit fails. Point configuration is automatically synchronized from the main unit to the standby unit. Hot standby requires both devices to have the same model and firmware version.\n\n**Cascade Deployment**: At the workshop level, multiple GTE-3000 units collect data nearby, and the data is aggregated to a GTE-3000Pro for edge computing and unified cloud upload, reducing the number of public network connections.\n\n## 10. Selection Recommendations\n\n- Less than 500 points, with wired network, no edge computing needs: GTE-3000\n- 500 to 3000 points, no network cables on site, requires 4G uplink: GTE-3000S\n- More than 3000 points, requires edge inference or CNC device connection: GTE-3000Pro\n\nThe point configuration format of all three devices is fully compatible. When upgrading from GTE-3000 to GTE-3000Pro later, export the configuration and import it directly, without needing to re-enter the points.',1462,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (162,206,126,NULL,0,'Standard chunk','GTE Series Gateway Field Installation and Maintenance Guide\n\nDocument Number: GL-OPS-2024-009\n\nVersion: V2.6\n\nModels covered: GTE-3000, GTE-3000S, and GTE-3000Pro\n\nPrepared by: Technical Service Department\n\n1. Preparation Before Operation\n\nBefore on-site operation, three confirmations must be completed: first, confirm that the ambient temperature at the installation location does not exceed 60°C long-term, and is away from strong interference sources such as inverters and large power contactors; second, confirm that the on-site power supply is DC 9V to 36V, and an independent circuit breaker is reserved; third, confirm the network conditions, wired access requires pre-laid network cables, and 4G/5G access requires confirmation that the signal strength on-site is no less than -95dBm.\n\nList of Tools:\n\n2. Installation steps\n\n1. Disconnect the on-site power supply, confirm the power indicator light is off before proceeding with wiring work.\n\n2. Insert the gateway\'s snap hook into the DIN rail, first hang the side then push down to secure, you can hear the snap hook in place sound; for wall mounting, use M4 screws to fix the four corners.\n\n3. Connect power supply: the 3-pin terminal from left to right is V+, V-, PE, PE must be connected to the grounding busbar of the cabinet, grounding resistance should not exceed 4Ω.\n\n4. Connecting to RS485: A connects to A, B connects to B, 120Ω terminal resistor is enabled at both ends of the bus, and the shield is grounded at one end',1490,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (163,206,126,NULL,1,'Standard chunk','.\n\n5. Connect Ethernet: LAN1 is the management port, LAN2 is the business port, after the network cable is done, use the tester to confirm the wiring order is T568B.\n\n6. Install the antenna for the wireless model, the antenna should be extended as much as possible outside the metal cabinet, installation inside the cabinet will cause signal attenuation of more than 10dB.\n\n7. Power on, observe the indicator lights: PWR constantly lit indicates normal power supply, SYS flashing once per second indicates normal system operation, COM flashing indicates data transmission and reception on the serial port.\n\n3. Commissioning and acceptance\n\nLaptop network port configured as 192.168.1.100/24, access https://192.168.1.10 via browser to log in to the Web interface, default account admin, default password Gl@2024, password must be changed upon first login.\n\nComplete sequentially: change the management port IP to the planned on-site address, configure the business port network, add southbound devices and points, configure northbound MQTT connection, start the collection group, confirm the status of each collection group is running on the operation monitoring page.\n\nAcceptance criteria:\n\n4. Daily maintenance\n\nMonthly maintenance: Check indicator light status, check if CPU and memory usage on the Web interface are consistently above 80%, check if remaining storage space is below 20%, export and archive operational logs.\n\nQualitative maintenance: clean dust on the device surface and heat sink, retighten power and serial port terminals, check if system time deviation exceeds 1 minute, and export a complete configuration file backup',1641,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:39');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (164,206,126,NULL,2,'Standard chunk','.\n\nAnnual maintenance: Check if the power adapter output voltage has decayed, evaluate if the firmware version needs to be upgraded, perform a master-slave switch exercise for dual-machine hot standby devices.\n\n5. Common on-site fault handling\n\nPWR light not lit: First measure the input voltage at the terminal, check the upstream circuit breaker and wiring if no voltage, if voltage exists but the device does not light up, replace the power adapter.\n\nSYS light flashing rapidly: System anomaly, first power off and reboot; if still flashing rapidly after reboot, export logs and contact technical service department.\n\nCOM light not flashing: No data transmission on the serial port, troubleshoot in the order of A/B wiring reversed, parameter inconsistency, slave station address error, missing terminal resistor.\n\nCollection group reports ERR-5021: Position configuration is incompatible with the protocol stack, commonly occurs after firmware upgrade across major versions, rollback firmware and reupgrade according to the transitional version.\n\nDevice frequently reboots: Troubleshoot in the order of stable power supply, environmental temperature exceeding 60°C, number of edge models exceeding 3.\n\n6. Safety precautions\n\nDo not connect wires while powered on; must work after disconnecting and testing for electricity.\n\nWear anti-static wristband before disassembling the motherboard, hold the motherboard edges, do not touch chip pins.\n\nUse safety harness for high-altitude work, use insulating ladder for cabinet top installation.\n\nAfter completing the job, count the tools to prevent metal tools from being left in the cabinet, causing short circuits',1661,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:39');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (165,206,126,NULL,3,'Standard chunk','.\n\n| Tool Name | Specification | Purpose |\n| --- | --- | --- |\n| Cross Screwdriver | PH1 / PH2 | Terminal tightening and housing disassembly |\n| Multimeter | Supports DC voltage 0-100V | Measuring input voltage and line voltage drop |\n| Network Cable Tester | RJ45 | Confirming cable continuity and wiring |\n| Notebook Computer | With network port or USB to network port | Configuration management and debugging |\n| Signal Strength Detector | Supports 4G/5G | Signal survey before wireless installation |\n| Anti-static Wristband | - | Preventing electrostatic breakdown when disassembling the motherboard |\n\n| Acceptance Item | Acceptance Standard | Inspection Method |\n| --- | --- | --- |\n| Power Supply Voltage | Measured 22V to 26V at the terminal | Measured with a multimeter |\n| Grounding Resistance | No more than 4Ω | Grounding resistance tester |\n| Serial Communication | Timeout rate of each slave station is less than 1% | Observing communication quality panel for 10 minutes |\n| Data Point | Randomly check 10 data points and compare with on-site instrument readings | On-site comparison |\n| Cloud Upload Link | Data forwarding status is connected, and data can be received on the platform side | Verification on the platform side |\n| Disconnection Recovery | Unplug the network cable for 5 minutes and then restore, data has no gaps | Query platform',1361,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:39');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (166,206,126,NULL,4,'Standard chunk','| Data can be received | Platform-side verification |\n| Disconnection Recovery | Unplug the network cable for 5 minutes and then restore, data has no gaps | Query platform historical curves\n| Restart Recovery | Automatic data collection resumes within 90 seconds after power-off restart | On-site power-off test',311,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (167,206,127,NULL,0,'Standard chunk','[Sheet: Fault Codes]\n| Fault code | Name | Severity | Trigger condition | Field troubleshooting | Affects data collection |\n| --- | --- | --- | --- | --- | --- |\n| ERR-1001 | Input voltage too low | Critical | Input remains below 9 V for more than 3 seconds. | Measure the voltage at the terminals. Check the upstream circuit breaker and wiring voltage drop. Replace the power adapter if needed. | Yes |\n| ERR-1002 | Input voltage too high | Critical | Input remains above 36 V for more than 1 second. | Disconnect power immediately. Verify the power supply rating. Use an industrial 24 V power supply. | Yes |\n| ERR-1005 | Internal temperature too high | Warning | The mainboard temperature sensor reads above 85 °C. | Check whether the device is near a heat source. Add airflow ducting or move the device to a cooler location. | No |\n| ERR-2003 | eMMC write failure | Critical | Write verification fails three times in a row. | Export the logs and return the unit for inspection. Replace the mainboard if the storage chip has reached the end of its life. | Yes |\n| ERR-2007 | Low storage space | Warning | Free storage falls below 10%. | Clear old logs on the System Maintenance page or reduce the local cache retention period. | No |\n| ERR-301',1246,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (168,206,127,NULL,1,'Standard chunk','| Storage Space Insufficient | Remaining storage space is below 10% | Clean up historical logs on the system maintenance page, or shorten the local cache retention period | No\n| ERR-3011 | RS485 communication timeout | Warning | The same slave device fails to respond for five consecutive collection cycles. | Check for reversed A/B wires, mismatched serial settings, an incorrect slave address, and missing termination resistors, in that order. | Partial |\n| ERR-3012 | High RS485 CRC error rate | Warning | CRC verification failures exceed 5% in 10 minutes. | Check protective earth, confirm the shield is grounded at one end only, and verify the bus length is within 1,200 m. | Partial |\n| ERR-3020 | Modbus slave returned an exception | Advisory | The slave returns exception code 01, 02, or 03. | Verify the register address and data type. Confirm that the device supports the requested function code. | Partial |\n| ERR-4002 | OPC UA session creation failed | Warning | The handshake with the OPC UA server fails. | Verify the endpoint, security policy, username, and password. Check whether the certificate has expired. | Partial |\n| ERR-4015 | S7 connection refused | Warning | The PLC refuses to establish the connection. | Verify the rack and slot numbers, and check whether the PLC has reached its connection limit. | Partial |',1337,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (169,206,127,NULL,2,'Standard chunk','| S7 Connection Refused | Confirm the PLC\'s rack and slot configuration, confirm that the number of allowed connections has not been exhausted | Partial\n| ERR-5021 | Data point configuration incompatible with protocol stack | Critical | A field cannot be parsed while the data point configuration is loading. | Often follows a major firmware upgrade. Roll back and upgrade again through the intermediate release. | Yes |\n| ERR-5022 | Data point count exceeds model limit | Warning | The configured data point count exceeds the device model\'s limit. | Remove data points or upgrade to a higher model. Limits are 2,000 for GTE-3000, 5,000 for GTE-3000S, and 20,000 for GTE-3000Pro. | Partial |\n| ERR-6003 | MQTT authentication failed | Critical | The broker returns CONNACK error code 4 or 5. | Verify the username, password, and ClientID. Confirm that the device is enabled on the platform. | No |\n| ERR-6008 | TLS handshake failed | Critical | Certificate validation fails or clocks are out of sync. | Check certificate validity and the CA chain. Check whether the device clock is off by more than five minutes. | No |\n| ERR-6012 | Local cache full | Warning | While offline, the number of cached records reaches the device model\'s limit. | Restore network access. Once the cache is full, the oldest records are discarded first.',1328,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (170,206,127,NULL,3,'Standard chunk','Local cache full | Warning | While offline, the number of cached records reaches the device model\'s limit. | Restore network access. Once the cache is full, the oldest records are discarded first. | No |\n| ERR-7001 | Edge rule syntax error | Advisory | The syntax parser fails when saving the rule. | Use the debugger on the Edge Rules page to identify the error line. Verify the field and stream names. | No |\n| ERR-7005 | Model loading failed | Warning | The ONNX model fails validation or exceeds 200 MB. | Verify the model format and operator version. Compress or prune the model before uploading it again. | No |\n| ERR-7009 | Insufficient memory for edge inference | Critical | Models running concurrently exceed the memory threshold. | Run fewer models concurrently. Use at most three per device as a guideline. | Partial |\n| ERR-8004 | Firmware signature verification failed | Critical | The firmware package signature does not match the device public key. | Download the package again from the official source and verify its SHA-256 checksum. | No |\n| ERR-8006 | Firmware model mismatch | Advisory | The model identifier in the firmware package differs from the device model. | GTE-3000 and GTE-3000S firmware packages are model-specific. Check the model identifier in the package name. | No |\n| ERR-9002 | Hot standby heartbeat lost | Warning |',1353,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (171,206,127,NULL,4,'Standard chunk','| Not compatible, check model identifier in package name | No |\n| ERR-9002 | Hot standby heartbeat lost | Warning | The standby device sends no heartbeat for five consecutive seconds. | Check the heartbeat cable. Confirm both devices have the same model and firmware version. | No |\n| ERR-9007 | System clock not synchronized | Advisory | NTP synchronization has failed continuously for more than 24 hours. | Verify the NTP server is reachable. Without internet access, use an internal NTP server or set the clock manually. | No |\n\n[Sheet: LED Status]\n| Indicator | Status | Meaning | Recommended action |\n| --- | --- | --- | --- |\n| PWR | Solid | Power supply is normal. | No action needed. |\n| PWR | Off | No incoming power or faulty power supply. | Measure the input voltage and replace the power adapter if needed. |\n| SYS | Flashes once per second | The system is running normally. | No action needed. |\n| SYS | Flashes quickly | System fault. | Power cycle the device. If the fault persists, export the logs and request service. |\n| SYS | Solid | The system is starting or has stopped responding. | Wait 90 seconds. If the light remains solid, power cycle the device. |\n| COM | Flashing | The serial port is sending or receiving data. | No action needed. |\n| COM | Not flashing | No data on the serial port. | Check the wiring and serial settings',1352,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (172,206,127,NULL,5,'Standard chunk','| COM | Not Flashing | No Data on Serial Port | Check wiring, serial port parameters, slave address |\n| COM | Not flashing | No data on the serial port. | Check the wiring, serial settings, and slave address. |\n| NET | Solid | The northbound connection is established. | No action needed. |\n| NET | Flashes slowly | Reconnecting. | Check the network and certificates. See ERR-6003 and ERR-6008. |\n| ALM | Solid | A critical alarm has not been acknowledged. | Sign in to the web interface and check the alarm list. |',515,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (173,206,128,NULL,0,'Standard chunk','Northline Industrial Systems GTE Series Firmware Upgrade and Release Notes\n\nDocument number: GL-PRD-2024-023\nVersion: V1.8\nModels covered: GTE-3000, GTE-3000S, and GTE-3000Pro\nMaintenance Department: Product Department Firmware Group\n\nI. Firmware Version Naming Convention\n\nFirmware version numbers are in the format 3.2.14-r5, with the following four segments:\n\n3   Major version number, incremented when there is a major hardware platform change or protocol stack restructure\n2   Minor version number, incremented when new features are added\n14  Revision number, incremented when defects are fixed\nr5  Release batch, re-packaging of the same revision number with no functional changes\n\n| Firmware with different main version numbers cannot be directly upgraded, for example, from 2.x to 3.x must first upgrade to transition version 2.9.20, then to 3.0.0. Jump version upgrade will cause configuration files to be unreadable, and all points will be lost after device boot |',974,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (174,206,128,NULL,1,'Standard chunk','.\n\nII. Current Maintenance Versions\n\n3.2.14-r5   Stable version, released in September 2024, recommended for production environments\n3.3.6-r2    Feature version, released in December 2024, supports 5G dual SIM dual standby and MQTT 5.0\n2.9.20-r8   Maintenance version, only fixes critical defects, maintenance stops on December 31, 2025\n\nIII. Major Changes in 3.3.6\n\nNew Features:\n1. MQTT 5.0 support, supports shared subscriptions and topic aliases, reducing message overhead by about 15% in long connection scenarios\n2. GTE-3000S and GTE-3000Pro support 5G dual SIM dual standby, automatically switching to the backup SIM within 30 seconds when the main SIM fails\n3. Collection groups support importing and exporting to Excel, including fields such as point name, register address, data type, and scaling coefficient\n4. Web interface adds a \"Communication Quality\" panel, displaying response time and timeout rate for each southbound device\n5. Edge rules support window functions, allowing calculation of 5-minute sliding averages\n\nBug Fixes:\n1. Fixed the occasional frame loss issue with RS485 at 115200bps over long periods, caused by the serial port driver buffer not being cleared in high load conditions\n2. Fixed the data order disorder issue during disconnection recovery, with the recovery queue now strictly sorted by timestamp\n3. | Configuration file import fixes DO |',1379,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:39');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (175,206,128,NULL,2,'Standard chunk','2. Fixed the data order disorder issue during disconnection recovery, with the recovery queue now strictly sorted by timestamp\n3. Fixed the issue where DO output status was not reset after importing a configuration file\n4. Fixed the issue where OPC UA Server did not release sessions after abnormal client disconnection, rejecting new connections after exceeding 64 sessions\n5. Fixed the issue where log timestamps were set to 1970 when the device time was not synchronized\n\nKnown Issues:\n1. GTE-3000Pro has high memory usage when running more than four ONNX models simultaneously, suggesting no more than three models per device\n2. FOCAS protocol connection to some older FANUC systems is slow on the first handshake, taking about 20 seconds\n\nIV. Pre-upgrade Preparation\n\n1. Export the current configuration from the Web interface under [System Maintenance] → [Configuration Management], with the filename recommended to include a date, for example line3-gw01-20241220.glcfg\n2. Export the last 7 days\' logs from [System Maintenance] → [Log Download], for comparison after upgrade\n3. Ensure the device power supply is stable, as power interruption during upgrade may damage the firmware, requiring factory re-flashing\n4. Verify that the current firmware version matches the target firmware version\'s major version number\n5. Notify relevant production line personnel that data collection will be interrupted for 3 to 5 minutes during the upgrade\n\nFive, Upgrade Operation Steps\n\nMethod One: Web Interface Upgrade (Recommended)\n\n1. | Access device management via browser |',1569,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (176,206,128,NULL,3,'Standard chunk','| 3 to 5 minutes |\n\nFive, Upgrade Operation Steps\n\nMethod One: Web Interface Upgrade (Recommended)\n\n1. Access the device management port https://192.168.1.10 via a browser and log in with an administrator account\n2. Navigate to [System Maintenance]→[Firmware Upgrade]\n3. Click \"Select File\" and upload the .glfw firmware package\n4. The system automatically verifies the signature and model compatibility. Once verification is successful, the \"Start Upgrade\" button becomes clickable\n5. Click \"Start Upgrade\", the page displays a progress bar. At this time, do not close the page or power off the device\n6. After the progress reaches 100%, the device automatically restarts. The Web interface will be accessible again approximately 60 seconds later\n7. After logging in, check the version number in [Operation Monitoring] to confirm it has been updated, and ensure all collection groups are in \"Running\" status\n\nMethod Two: Batch Upgrade\n\n| Use Northline Industrial Systems device management platform for batch deployment when more than 20 devices |',1047,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:39');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (177,206,128,NULL,4,'Standard chunk','. The platform pushes firmware in groups, supporting batch gray release: first upgrade 10% of devices, observe 24 hours without anomalies, then push the remaining devices.\n\nSix, Handling Upgrade Failures\n\nPhenomenon One: After uploading the firmware package, it prompts \"Signature Verification Failed\"\nThe cause is that the firmware package is incomplete or from an untrusted source. Redownload from the official channel and verify the SHA256 checksum\n\nPhenomenon Two: Prompt \"Model Mismatch\"\nThe firmware package for GTE-3000 and GTE-3000S is not interchangeable. Check the model identifier in the package name\n\nPhenomenon Three: The device is inaccessible after the upgrade\nFirst confirm whether the management port IP has changed. Access 192.168.1.10 directly. If still inaccessible, hold RESET for 10 seconds to restore factory settings, then import the configuration file exported before the upgrade\n\nPhenomenon Four: The collection groups do not run after the upgrade, and the log shows ERR-5021\nThis is due to incompatibility between the point configuration and the new version protocol stack, commonly seen when upgrading from 2.x to 3.x. Roll back to the version before the upgrade, and reupgrade through the 2.9.20 transitional version\n\nSeven, Firmware Rollback\n\nDevices retain the firmware image of the previous version. Click \"Rollback to Previous Version\" on the [System Maintenance] → [Firmware Upgrade] page. The rollback process takes approximately 2 minutes. Only one historical version is retained. After two consecutive upgrades, rollback to an earlier version is not possible.',1596,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (178,206,128,NULL,5,'Standard chunk','. Only one historical version is retained. After two consecutive upgrades, rollback to an earlier version is not possible.\n\nAfter rollback, the configuration file will automatically downgrade to be compatible, but new configuration items in the new version will be lost, for example, when rolling back from 3.3.6 to 3.2.14, the 5G dual-card configuration and window function rules will be cleared\n\nEight, Version Support Period\n\nNorthline Industrial Systems Inc. Spare Parts Supply and Return Policy',499,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (179,207,129,NULL,0,'Parent chunk','# Northline Industrial Systems Inc. Employee Handbook\n\nDocument Number: GL-HR-2024-001\nVersion: V4.1\nEffective Date: July 1, 2024\nInterpretation Department: Human Resources Department\n\n## Chapter One General Provisions\n\nArticle 1: To standardize company management and clarify employees\' rights and obligations, this handbook is formulated based on the \"company employment policy,\" the \"individual employment agreements,\" and other relevant laws and regulations, combined with the company\'s actual situation.\n\nArticle 2: This handbook applies to all employees who have signed labor contracts with the company, including regular employees and those in the probationary period. Interns and dispatched workers are subject to this handbook, unless otherwise agreed.\n\nArticle 3: Employees must carefully read this handbook and sign a confirmation upon joining. This handbook takes effect from the date of implementation, and any previous regulations inconsistent with this handbook will be replaced by this handbook.\n\n## Chapter 2: Onboarding and Probationary Period\n\nArticle 4: New employees must submit the following documents upon reporting for duty: original and copies of ID card, highest academic degree and diploma, proof of termination of previous employment, health examination report, copies of bank cards, and two one-inch photos. Academic information will be verified by the Human Resources Department through the approved credential-verification provider.\n\nArticle 5: If false documents are provided, the company has the right to terminate the labor contract without paying economic compensation. If discovered after employment, it will be treated as a serious disciplinary offense.\n\nArticle 6: The probation period is determined based on the term of the labor contract:\n\n- If the labor contract term is more than 1 year but less than 3 years, the probation period is 2 months\n- If the labor contract term is more than 3 years, the probation period is 6 months\n- If the labor contract term is more than 3 months but less than 1 year, the probation period is 1 month\n\nArticle 7: The probationary salary is 80% of the regular salary, and shall not be lower than the minimum wage standard in the company\'s location. For R&D positions, the probationary salary is 90% of the regular salary.\n\nArticle 8: 15 working days before the expiration of the probationary period, staff submit a request for conversion, the assessment is completed by their immediate supervisor and approved by the head of department.\n\nArticle 9: Employees on probation must give 3 days\' written notice before leaving; formal employees must give 30 days\' written notice before leaving.\n\n## Chapter Three Working Hours\n\nArticle 10: The company implements a standard working hours system, with 8 hours of work per day and 5 days of work per week. The working hours are from 9:00 to 18:00, with 12:00 to 13:00 as the lunch break.\n\nArticle 11: Production departments implement a comprehensive working hours system, with a monthly cycle and total monthly working hours not exceeding the statutory standard. Specific shift arrangements are formulated by the Production Department and reported to the Human Resources Department for record.\n\nFlexible work: Research and development, design and product jobs can apply for flexible working hours ranging from 8:30 to 10:00.\n\nArticle 13: Overtime must be applied for in advance through the OA system and approved by the direct supervisor to be valid. Voluntary extended work without approval does not count as overtime. Overtime can be compensated by either taking compensatory leave or receiving overtime pay, with compensatory leave valid for 3 months from the date of overtime.\n\n## Chapter Four Salary and Benefits\n\nArticle 14: The salary structure is: monthly total income = basic salary + position salary + performance salary + allowances. Basic salary and position salary are fixed, while performance salary fluctuates based on quarterly performance evaluations.',3981,NULL,NULL,NULL,'Pending embedding','2026-09-04 02:18:44','2026-11-16 22:56:40');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (180,207,129,179,0,'Child chunk','# Northline Industrial Systems Inc. Employee Handbook\n\nDocument Number: GL-HR-2024-001\nVersion: V4.1\nEffective Date: July 1, 2024\nInterpretation Department: Human Resources Department\n\n## Chapter One General Provisions\n\nArticle 1: To standardize company management and clarify employees\' rights and obligations, this handbook is formulated based on the \"company employment policy,\" the \"individual employment agreements,\" and other relevant laws and regulations, combined with the company\'s actual situation.\n\nArticle 2: This handbook applies to all employees who have signed labor contracts with the company, including regular employees and those in the probationary period. Interns and dispatched workers are subject to this handbook, unless otherwise agreed.\n\nArticle 3: Employees must carefully read this handbook and sign a confirmation upon joining. This handbook takes effect from the date of implementation, and any previous regulations inconsistent with this handbook will be replaced by this handbook.\n\n## Chapter Two: Onboarding',1039,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:40');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (181,207,129,179,1,'Child chunk','Where the provisions of this manual differ from the regulations, this manual shall prevail.\n\n## Chapter 2: Onboarding and Probationary Period\n\nArticle 4: New employees must submit the following documents upon reporting for duty: original and copies of ID card, highest academic degree and diploma, proof of termination of previous employment, health examination report, copies of bank cards, and two one-inch photos. Academic information will be verified by the Human Resources Department through the approved credential-verification provider.\n\nArticle 5: If false documents are provided, the company has the right to terminate the labor contract without paying economic compensation. If discovered after employment, it will be treated as a serious disciplinary offense.\n\nArticle 6: The probation period is determined based on the term of the labor contract:\n\n- If the labor contract term is more than 1 year but less than 3 years, the probation period is 2 months\n- If the labor contract term is more than 3 years, the probation period is 6 months\n- If the labor contract term is more than 3 months but less than 1 year, the probation period is 1 month\n\nArticle 7: The probationary salary is 80% of the regular salary, and shall not be lower than',1247,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:40');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (182,207,129,179,2,'Child chunk','1 month\n\nArticle 7: The probationary salary is 80% of the regular salary, and shall not be lower than the minimum wage standard in the company\'s location. For R&D positions, the probationary salary is 90% of the regular salary.\n\nArticle 8: 15 working days before the expiration of the probationary period, staff submit a request for conversion, the assessment is completed by their immediate supervisor and approved by the head of department.\n\nArticle 9: Employees on probation must give 3 days\' written notice before leaving; formal employees must give 30 days\' written notice before leaving.\n\n## Chapter Three Working Hours\n\nArticle 10: The company implements a standard working hours system, with 8 hours of work per day and 5 days of work per week. Working hours are from 9:00 to 18:00, during which',803,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:23:17');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (183,207,129,179,3,'Child chunk','5 days of work per week. Working hours are from 9:00 to 18:00, with 12:00 to 13:00 as the lunch break.\n\nArticle 11: Production departments implement a comprehensive working hours system, with a monthly cycle and total monthly working hours not exceeding the statutory standard. Specific shift arrangements are formulated by the Production Department and reported to the Human Resources Department for record.\n\nFlexible work: Research and development, design and product jobs can apply for flexible working hours ranging from 8:30 to 10:00.\n\nArticle 13: Overtime must be pre-approved through the OA system and approved by the direct supervisor to be valid. Voluntary extended work without approval does not count as overtime. Overtime can be compensated by either taking compensatory leave or receiving overtime pay according to regulations. Compensatory leave is valid for 3 months from the date of overtime.',908,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:23:17');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (184,207,129,179,4,'Child chunk','Choosing compensatory leave or receiving overtime pay according to regulations, compensatory leave is valid for 3 months from the date of overtime.\n\n## Chapter Four Salary and Benefits\n\nArticle 14: The salary structure is: monthly total income = basic salary + position salary + performance salary + allowances. Basic salary and position salary are fixed, while performance salary fluctuates based on quarterly performance evaluations.',435,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-09-04 10:23:17');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (185,207,129,NULL,1,'Parent chunk','Article 15: Salary is paid on the 15th of each month, and if it falls on a holiday, it will be paid on the nearest working day. Salaries are transferred via bank, and personal income tax is withheld and paid by the company.\n\nArticle 16: The company provides the benefits described in each employee\'s agreement. Human Resources explains health coverage, retirement savings options, and payroll deductions during onboarding.\n\nArticle 17: Allowance items:\n\n- Lunch allowance: 30 CAD per working day, paid together with salary\n- Transportation allowance: 200 CAD per month, 500 CAD per month for fieldwork positions\n- Communication allowance: 100 CAD per month, 300 CAD per month for sales and after-sales positions\n- High-temperature allowance: 300 CAD per month from June to September\n- On-site allowance: 150 CAD per day for employees who stay on-site at the client\'s location for at least 5 consecutive working days\n\nArticle 18: Annual benefits include: one annual health check-up, 500 CAD birthday gift, 1000 CAD wedding gift, 1000 CAD maternity gift, and festival gifts for the year-end holiday and the company anniversary. Employees with 3 years of service receive an upgraded comprehensive health check-up package.\n\nArticle 19: Annual bonus is linked to the company\'s annual business performance and individual performance, generally paid in February of the following year. Employees who have left before the payment date are not eligible for the bonus.\n\n## Chapter Five Performance Management\n\nArticle 20: The company implements quarterly performance evaluations, with evaluation periods from January to March, April to June, July to September, and October to December each year.\n\nArticle 21: The evaluation grades are divided into S, A, B, C, and D, corresponding to performance coefficients of 1.5, 1.2, 1.0, 0.8, and 0. The proportion of S grades within a department shall not exceed 10%, and A grades shall not exceed 30%.\n\nArticle 22 Employees who receive a C rating for two consecutive quarters shall enter a 3-month performance improvement plan. If they fail to meet the standards by the end of the improvement period, the company may reassign them or terminate their employment in accordance with the law.\n\nArticle 23 Employees who receive a D rating in a single quarter shall receive zero performance-based salary for that quarter and shall undergo a face-to-face discussion with their department head and the Human Resources Department.\n\n## Chapter Six Training and Development\n\nArticle 24 New employees shall attend a 3-day onboarding training covering company overview, product knowledge, rules and regulations, and information security. Those who fail the training may take one make-up exam.\n\nArticle 25 Technical positions shall receive no less than 40 hours of professional training annually. For external training organized by the company, if the single session cost exceeds 5,000 CAD, the employee must sign a training service agreement with a service period of 2 years. If the employee resigns voluntarily during the service period, the company shall refund the training fees proportionally based on the number of unfulfilled months.\n\nArticle 26 Employees may apply for internal job transfers. Those who have been employed for at least one year and have a performance rating of B or higher are eligible to apply. The transfer must be approved by both the original and receiving departments, and the employee will have a 1-month adaptation period after the transfer.\n\n## Chapter Seven Code of Conduct\n\nArticle 27 Employees shall abide by professional ethics and shall not engage in part-time work that competes with the company\'s business or use their position for personal gain.\n\nArticle 28 Employees shall not accept cash, securities, or valuable items from suppliers or customers. Gifts received for business purposes with a value exceeding 500 CAD shall be reported to the Administration Department for registration and handling.\n\nArticle 29 Employees in confidential positions must complete the handover of confidential matters upon leaving and comply with the terms of the non-compete agreement. The maximum non-compete period shall not exceed 2 years, and the company shall pay monthly compensation.\n\nArticle 30: Serious disciplinary violations include, but are not limited to: leaking company trade secrets, forging reimbursement documents, and consecutive absence from work for 3 days',4415,NULL,NULL,NULL,'Pending embedding','2026-09-04 02:18:44','2026-11-16 22:56:40');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `document_id`, `parent_id`, `chunk_index`, `chunk_type`, `content`, `char_count`, `page_no`, `title_path`, `extra_meta`, `vector_status`, `create_time`, `update_time`) VALUES (186,207,129,185,5,'Child chunk','Article 15: Salary is paid on the 15th of each month, and if it falls on a holiday, it will be paid on the nearest working day. Salaries are transferred via bank, and personal income tax is withheld and paid by the company.\n\nArticle 16: The company provides the benefits described in each employee\'s agreement. Human Resources explains health coverage, retirement savings options, and payroll deductions during onboarding.\n\nArticle 17: Allowance items:\n\n- Lunch allowance: 30 CAD per working day, paid together with salary\n- Transportation allowance: 200 CAD per month, 500 CAD per month for fieldwork positions\n- Communication allowance: 100 CAD per month, 300 CAD per month for sales and after-sales positions\n- High-temperature allowance: 300 CAD per month from June to September\n- On-site allowance: 150 CAD per day for employees who stay on-site at the client\'s location for at least 5 consecutive working days\n\nArticle 18: Annual benefits',944,NULL,NULL,NULL,'Completed','2026-09-04 02:18:44','2026-11-16 22:56:40');
