INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (98,356,268,135,'.\n\nSix. Exchange Policy\n\n(1) Exchange During Warranty Period\n\nIf the same fault occurs in the device during the warranty period and remains unresolved after two repairs, an exchange can be requested. The warranty period of the new device is calculated based on the remaining warranty period of the original device, with a minimum of 3 months if less than 3 months remains\n\nIf non-human functional faults occur within 30 days of delivery, a new device can be directly requested for exchange without prior repair\n\n(2) Model Upgrade Exchange\n\nWithin 90 days after procurement, if the project requires an upgrade to a higher model (e.g., GTE-3000 to GTE-3000S), a price difference can be applied for to exchange the equipment. The price difference = new model price - original model price × 0.9, where 0.9 is the depreciation coefficient',0.031498,3,'BM25 search+Vector search','2026-09-04 03:42:51');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (99,356,247,134,'. The serial number is located on the nameplate on the side of the equipment, with the format GL3000-YYWW-XXXXX\n\n### Q8: How long does the repair usually take?\n\nRepair method: After the customer sends the device, we will complete the inspection and repair within 5 working days and return it. The round-trip shipping costs during the warranty period are covered by the company, while customers are responsible for the shipping costs outside the warranty period.\n\nOn-site service method: This is only applicable to customers who have purchased the on-site service package or projects with a single purchase of more than 50 units. In major service cities, the service team will arrive on-site within 24 hours, while in regional business destinations, it will arrive within 48 hours.\n\n### Q9: Can a spare device be borrowed?\n\nCustomers who sign an annual service agreement can apply for the use of a spare unit, with a maximum borrowing period of 15 days',0.031281,4,'BM25 search+Vector search','2026-09-04 03:42:51');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (100,356,232,133,'[Page 1]\nNorthline Industrial Systems Inc.\nAfter-Sales Service and Warranty Policy\nDocument Number: GL-SVC-2024-002\nVersion: V4.2\nEffective Date: August 1, 2024\nResponsible Department: Customer Service Center\nArticle 1 Scope of Application\nThis clause applies to GTE series industrial intelligent gateways and their accessories purchased by customers from Northline Industrial Systems Inc. In case of specific agreements in the sales contract, such agreements shall prevail; for matters not specified in the contract, this clause shall apply.\nArticle 2 Quality Guarantee Period\n1. The whole machine quality guarantee period for GTE-3000, GTE-3000S, and GTE-3000Pro is 24 months from the date of manufacture. The warranty period shall be based on the factory date indicated on the equipment nameplate.\n2. If the customer can provide valid purchase proof, the warranty period may be calculated from the purchase date, with a maximum extension of 3 months.\n1. The GTE-3000, GTE-3000S, and GTE-3000Pro carry a warranty from the factory date\nthat lasts 24 months',0.016129,5,'Vector search','2026-09-04 03:42:51');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (101,356,264,135,'. During the support period, spare parts will be supplied based on existing inventory. If the inventory is exhausted, alternative solutions will be provided, including discounted trade-in or migration to the GTE-3000 series\n\nSpare Parts for Discontinued Models Are Not Acceptable for Returns.\n\nV. Return Policy\n\n(I) Eligible for Return\n\n1. Within 7 Days of Delivery, If the Equipment Is Unopened, Packaging Intact, and Accessories Complete, and the Customer Requests a Return for Reasons Related to the Customer, a No-Reason Return Can Be Applied, with the Customer Bearing Round-Trip Freight, and the Company Not Charging Depreciation Fees.\n2. If the equipment is confirmed to have quality issues and cannot be resolved through repair within 15 days of delivery, it can be returned. The company will cover the round-trip shipping costs, and the full payment will be refunded',0.015625,6,'Vector search','2026-09-04 03:42:51');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (102,356,273,135,'. After the warranty period, customers can purchase and replace the motherboard themselves, but the equipment will no longer be covered by the full warranty, and only the motherboard itself will have a 6-month warranty\n\nQ: Does the spare part have a warranty?\nA: Yes. Spare parts purchased separately are warranted for 6 months from the date of receipt. Spare parts replaced during a full system repair will carry the remaining warranty period of the system, with any remaining period less than 3 months counted as 3 months.',0.015385,7,'BM25 search','2026-09-04 03:42:51');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (103,356,233,133,'. The warranty period is based on the manufacturing date indicated on the equipment nameplate.\n(ii) A maximum of 3 extensions for customers who can provide valid purchase vouchers, based on the date of purchase\nMonth.\nThree. The warranty period for accessories such as power adapters, antennas, terminals, rail clips, etc., is 12 months.\nFour. Spare parts purchased separately are warranted for 6 months from the date of receipt; spare parts replaced during whole machine repair follow the remaining warranty period of the whole machine, with a minimum of 3 months if less than 3 months remain.\nFive. If a fault is not resolved after two repairs within the warranty period, the customer may request a replacement. The warranty period of the new equipment is calculated based on the remaining warranty period of the original equipment, with a minimum of 3 months if less than 3 months remain.\nSix. Free warranty scope\nDuring the warranty period, functional faults caused by design, material, or manufacturing process defects are covered by free repair or replacement, including but not limited to: motherboard component failure, interface soldering issues, power module anomalies, wireless module non-recognition, and storage chip write failure.\nMonthly calculation',0.015152,8,'BM25 search','2026-09-04 03:42:51');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (104,358,203,131,'Northline Industrial Systems Inc. Attendance and Leave Policy\n\nDocument Number: GL-HR-2024-006\nVersion: V2.3\nEffective Date: July 1, 2024\nResponsible Department: Human Resources Department\n\nChapter One: Attendance Regulations\n\nArticle 1: All employees must participate in attendance tracking. The attendance method is dual recording via the workforce portal location check-in and door access card swipe, with the workforce portal records as the primary reference, and door access records for anomaly verification.\n\nArticle 2: Two check-ins per day: one for morning arrival and one for evening departure. If the number of missed check-ins in a month does not exceed 3, the employee may submit a make-up check-in application via OA, which must be approved by the supervisor and will not be counted as an anomaly. If it exceeds 3, from the 4th missed check-in onwards, each instance will be treated as a late arrival.\n\nArticle 3: Tardiness and Early Departure:\nArriving at work within 30 minutes after the scheduled start time is considered tardy, and leaving before the scheduled end time by 30 minutes is considered early departure.\nNo deductions will be made if the total number of tardy or early departures in a month does not exceed 2 times.\nStarting from the third occurrence, a deduction of 50 CAD will be made each time, and the performance evaluation will be downgraded by one level if the total exceeds 5 times in a month.\n\nArticle 4: Absence without prior approval:\n\nIf an employee arrives more than 30 minutes after the scheduled start time without prior approval, it will be treated as a half-day absence. If the employee does not show up for the entire day without proper leave procedures, it will be treated as a full-day absence.\nArticle 5: Absence Handling:\nA full-day absence will result in a deduction of twice the daily wage.\n\nIf an employee is absent for 3 consecutive days or accumulates 5 days of absence in a year, the company may terminate the employment contract according to the Employee Handbook, Article 30.\n\nArticle 6: Out-of-office and business trip periods:\n\nIf an employee cannot clock in during out-of-office or business trip periods, they must submit an out-of-office or business trip application on OA, and the system will automatically exempt them from clocking in after approval. For employees stationed at customer sites, the project manager will uniformly confirm attendance in the weekly report.\n\nChapter 2: Types and Standards of Leave\n\nArticle 8: Annual Leave Entitled by Law:\n\nAn employee who has worked for a cumulative period of 1 to 10 years is entitled to 5 days of annual leave; 10 to 20 years, 10 days; and 20 years or more, 15 days. The cumulative work experience includes the time worked at other companies, and it is based on the social security payment records or the termination certificate.\n\nArticle 9: Company Benefits Leave:\n\nAn employee who has worked for at least 1 year in the company is entitled to an additional 2 days of benefits leave; 3 years, 4 days; and 5 years, 6 days. Benefits leave and statutory leave are combined for use, and it is valid for the current year, not carried over to the next year, and not converted into salary.\n\nArticle 10: Sick Leave:\nSick leave must be supported by a sick leave note and registration records from a hospital of level two or higher. If the total sick leave in a year does not exceed 10 days, it will be paid at 80% of the basic salary; for days exceeding 10, it will be paid at 80% of the local minimum wage standard.\nIf the sick leave exceeds 15 days consecutively, the employee must submit a return-to-work certificate before resuming work.\n\nThe medical leave is determined based on the length of service according to national regulations, and the company will not terminate the employment contract during the medical leave period.\n\nArticle 11: Personal Leave:\nPersonal leave is unpaid leave, and the salary will be deducted according to the daily wage standard. Daily wage = monthly wage ÷ 21.75.\nFor personal leave not exceeding 3 days, approval from the department head is required; for more than 3 days, approval from the vice president in charge is required; for more than 10 days, approval from the general manager is required.\n\nIf the total personal leave exceeds 20 days in a year, the employee will lose the eligibility for the annual bonus for that year.\n\nThose who are legally married are entitled to 13 days of wedding leave (including 3 days as stipulated by the state and 10 days as a local reward), including weekends and public holidays. Wedding leave must be taken within the month of obtaining the marriage certificate.',0.362394,1,'BM25 search+Vector search→Rerank→Parent chunk expansion','2026-09-04 03:42:56');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (105,360,254,134,'If the status is \"Connected\", it indicates that the network and authentication are normal, and the issue is likely in topic mapping or platform-side subscription; if the status is \"Reconnecting\", it indicates network or certificate issues. Check if the device can ping the platform domain name, whether the certificate has expired, and whether the system time is accurate. System time deviation exceeding 5 minutes can cause TLS handshake failure\n\n## IV. Faults and Alarms\n\n### Q14: What does the error code ERR-5021 mean?\n\nERR-5021 indicates incompatibility between point configuration and the protocol stack, commonly occurring after cross-major version firmware upgrades. The solution is to roll back to the firmware version before the upgrade, and follow the instructions in the [Firmware Upgrade and Version Release Notes] to first upgrade to the transitional version before the target version.\n\n### Q15: Why does the device frequently restart?\n\nThe three most common reasons are:\n\n1. Yes. Download the Excel template from [Device Management] → [Point Management], fill in the point name, register address, data type, scaling coefficient, unit, and other fields according to the template, and import it. Single import is limited to no more than 5000 rows, and batch imports are required if exceeded',0.829305,1,'Agentic search','2026-09-04 03:43:01');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (106,360,248,134,'. The spare unit is of the same model or a higher model. The configuration during the borrowing period will be assisted by our engineers. A daily usage fee of 1% of the original equipment price will be charged if the equipment is not returned on time\n\n## III. Installation and Commissioning\n\n### Q10: What should I do if I forget the device management port IP?\n\nLong press the RESET button on the equipment panel for more than 10 seconds to restore the equipment to factory settings. The management port IP will be restored to 192.168.1.10, with the default account admin and default password Gl@2024. Restoring to factory settings will clear all point configuration. Please try other methods to recover the equipment first, such as using a network scanning tool to find the host with the MAC prefix 8C:1F:64 in the network segment',0.603541,2,'Agentic search','2026-09-04 03:43:01');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (107,360,253,134,'Q12: After data is uploaded to the cloud, the platform does not receive it. Where to start checking\n\n### Q13: Can point configurations be imported in bulk?\n\nCheck the connection status on the [Data Forwarding] page',0.595112,3,'Agentic search','2026-09-04 03:43:01');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (108,360,251,134,'GTE-3000 series product technical manual\n\n### GTE series on-site installation and maintenance operation guide',0.580170,4,'Agentic search','2026-09-04 03:43:01');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (109,360,246,134,'?\n\nChoose any of the following three methods:\n\n1. Call the service hotline at 416-555-0147, from 8:30 to 20:30 on weekdays, and 9:00 to 18:00 on holidays\n2. Submit an online service ticket on the Northline Industrial Systems official website under the [Service Support] section\n3. Contact the assigned sales manager or after-sales engineer\n\nWhen reporting a repair, please provide the equipment serial number (SN), description of the fault phenomenon, time of fault occurrence, on-site photos or log files',0.576325,5,'Agentic search','2026-09-04 03:43:01');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (110,364,267,135,'. We will complete the appearance and function inspection within 3 working days after receiving the goods\n5. Refund is processed within 5 working days after the inspection passes, and the refund is returned via the original payment method\n\nIf the inspection reveals that the equipment has been damaged by human factors, the return application will be canceled, and the equipment will be sent back to the customer, with the shipping costs borne by the customer',0.631210,1,'Agentic search','2026-09-05 15:11:54');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (111,364,266,135,'.\n\n(II) Not Eligible for Return\n\n1. More Than 15 Days After Delivery\n2. The Equipment Has Been Put into Use and Has Caused Wear, Scratches, or Terminal Deformation\n3. Seal Broken or Self-Disassembly\n4. Devices with Custom Firmware or Custom Hardware Configuration\n5. Devices Converted from Trial to Purchase (Trial Period Is the Acceptance Period)\n6. Devices for promotion, clearance, and special price sales of sample units\n\n(3) Return Process\n\n1. Customers submit a return application, noting the device serial number, purchase order number, and reason for return, along with on-site photos\n2. Customer Service Center reviews and responds within 2 working days\n3. After approval, customers return the device, with a copy of the return application attached inside the packaging\n4. We complete the appearance and function inspection within 3 working days after receiving the device\n5. Testing',0.538573,2,'Agentic search','2026-09-05 15:11:54');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (112,364,265,135,'.\n3. If the delivered model and configuration do not match the contract and the customer does not accept replacement, the equipment can be returned, and all costs will be borne by the company',0.537121,3,'Agentic search','2026-09-05 15:11:54');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (113,364,270,135,'.\n\n(3) Exchange Process\n\n1. Submit an exchange application, noting the original device serial number and target model\n2. After approval, the company will first send the new device (the customer must provide a deposit or sign a Device Return Commitment Letter)\n3. The customer returns the original device within 10 working days after receiving the new device\n4. After inspecting the original device and confirming no human damage, the deposit is refunded or the commitment letter is released\n5. If the original device is not returned on time, a charge will be issued based on the original price of the new device\n\nSeven. Packaging Requirements for Repairs and Returns\n\n1. Use the original factory packaging box; if unavailable, use a hard cardboard box with no less than 5 layers of corrugated paper\n2. Fill the device around with shock-absorbing material of no less than 3 centimeters thickness\n3. Small parts such as terminals and antennas should be individually bagged to avoid scratching the motherboard during transportation',0.523996,4,'Agentic search','2026-09-05 15:11:54');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (114,364,272,135,'.\n\nEight. Common Issues\n\nQ: Where can I find the device serial number?\nA: The serial number is printed on the device\'s side label, with the format GL3000-YYWW-XXXXX, where YY represents the last two digits of the manufacturing year and WW represents the manufacturing week. It can also be viewed at the top of the Web interface\'s [Operation Monitoring] page\n\nQ: How to handle the invoice when returning?\nA: The original copy of the issued VAT special invoice must be returned. We will process the refund after receiving the original invoice. If the invoice has been authenticated and claimed for tax deduction, the customer must issue a red invoice information form\n\nQ: Can I just replace the motherboard and repair it myself?\nAnswer: Disassembling the equipment during the warranty period will result in the loss of warranty eligibility',0.505766,5,'Agentic search','2026-09-05 15:11:54');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (115,366,156,125,'LAN2 is default as business port, with factory configuration as DHCP client. LAN3 and LAN4 of GTE-3000S and GTE-3000Pro can be configured as switch ports, cascading downstream devices\n\nWhen the management port IP is forgotten, hold the RESET button for more than 10 seconds to restore factory settings, returning the management port IP to 192.168.1.10. Restoring factory settings will clear all collected point configurations; make sure to export the configuration file before operation.\n\n### 3.3 Serial Ports\n\nRS485 uses a 2-pin terminal with A and B lines. Serial port parameters support 1200 ~ 115200bps, default 9600bps, 8 data bits, 1 stop bit, no parity check. A maximum of 32 slave devices can be connected on the same 485 bus, with 120Ω terminal resistors required at both ends of the bus. GTE-3000S and GTE-3000Pro have built-in terminal resistors that can be enabled via a dip switch.\n\n### 3.4 Digital Input/Output\n\nGTE-3000Pro provides 4 routes DI and 2 paths DO. DI is inputted for dry interfaces, which are relay output, contact capacity 30VDC/2A. DO is often used to connect sound alarms and to export signals when collecting breaks or threshold limits',0.032266,1,'BM25 search+Vector search','2026-09-05 15:14:07');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (116,366,158,125,'New data points beyond the point limit will be rejected, and the web configuration page will prompt \"Number of data points exceeds the current model limit\"\n\n## 5. Data Collection and Reporting Mechanism\n\nCollection tasks are organized by \"Collection Groups.\" A collection group includes several data points, a collection cycle, and a reporting strategy. The minimum collection cycle is 100ms, maximum 3600s. Reporting strategies include three types:\n\n**Periodic Reporting**: Pack the latest value and report it at fixed intervals, independent of the collection cycle configuration. Suitable for trend data, such as temperature, current.\n\n**Change Reporting**: Report only when the value changes beyond the set deadband threshold. Suitable for state data, significantly reducing traffic. Deadband threshold supports absolute value and percentage formats.\n\n**Hybrid Reporting**: Immediately report upon change, while also reporting once at a longer heartbeat cycle to ensure the upper system receives the latest value even if it missed the change event. Recommended for production environments.\n\nData is stored in local cache when the network is down. GTE-3000 has a cache capacity of 100,000 entries, GTE-3000S has 500,000, and GTE-3000Pro has 5,000,000. After network recovery, data is resent in chronological order, with a default transmission rate limit of 200 entries per second to avoid overwhelming the upper system. When the cache is full, the oldest data is discarded on a first-in-first-out basis.\n\n## 6. Edge Computing\n\nGTE-3000Pro supports running edge rules and lightweight models on the device',0.032002,2,'BM25 search+Vector search','2026-09-05 15:14:07');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (117,366,154,125,'.\n\nThere are three models in the series, with consistent hardware platforms, and differences mainly lie in computing power, number of interfaces, and wireless capabilities:\n\n| Model | Processor | Memory | Storage | Ethernet Port | Serial Port | Wireless | Typical Power Consumption |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| GTE-3000 | Quad-core 1.2GHz | 2GB | 8GB eMMC | 2 × Gigabit | 2 × RS485 | None | 6.5W |\n| GTE-3000S | Quad-core 1.2GHz | 4GB | 16GB eMMC | 4 × Gigabit | 4 × RS485/RS232 | 4G Full Network Coverage | 9.2W |\n| GTE-3000Pro | Eight-core 1.8GHz | 8GB | 64GB eMMC | 4 × Gigabit | 4 × RS485/RS232 | 5G + Wi-Fi 6 | 15.8W |\n\nGTE-3000 is the basic model, suitable for small-scale data collection on a single production line; GTE-3000S adds 4G uplink and more serial ports, suitable for workshops without wired networks; GTE-3000Pro has local inference capabilities, allowing lightweight vision detection models to run at the edge',0.031778,3,'BM25 search+Vector search','2026-09-05 15:14:07');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (118,366,157,125,'. DO is often used for connecting sound alarms to export signals when collecting breaks or thresholds.\n\n## 4. Protocol Support\n\nProtocols supported by the device facing field equipment:\n\n- Modbus RTU / Modbus TCP\n- OPC UA Client\n- Siemens S7(S7-200 Smart / S7-1200 / S7-1500)\n- Mitsubishi MC Protocol (3E Frame)\n- Omron FINS\n- Mitsubishi FX Series Programming Port Protocol\n- CNC Equipment\'s FOCAS Protocol (Only supported by GTE-3000Pro)\n\nProtocols supported by the device facing upper-level systems:\n\n- MQTT 3.1.1 / MQTT 5.0, supporting TLS encryption and mutual certificate authentication\n- HTTP / HTTPS Active Reporting\n- OPC UA Server\n- Standard access to AWS IoT and Azure IoT platforms\n\nGTE-3000 can be configured with up to 2000 data points, GTE-3000S with 5000, and GTE-3000Pro with 20000. New data points beyond the point limit will be rejected, and the web configuration page will prompt \"Number of data points exceeds the current model limit\"',0.031754,4,'BM25 search+Vector search','2026-09-05 15:14:07');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (119,366,161,125,'The upgrade process takes about 3 to 5 minutes, during which data collection is interrupted. After upgrade, the device automatically restarts and restores the original configuration\n\n## 9. Typical Deployment Methods\n\n**Single Machine Deployment**: One GTE-3000 connects to a PLC and instruments on a production line, and connects to the workshop switch via LAN2, with data reporting to the plant-level MES.\n\n**Dual Machine Hot Standby**: Two GTE-3000S units are interconnected via a heartbeat line. The standby unit takes over within 5 seconds if the main unit fails. Point configuration is automatically synchronized from the main unit to the standby unit. Hot standby requires both devices to have the same model and firmware version.\n\n**Cascade Deployment**: At the workshop level, multiple GTE-3000 units collect data nearby, and the data is aggregated to a GTE-3000Pro for edge computing and unified cloud upload, reducing the number of public network connections.\n\n## 10. Selection Recommendations\n\n- Less than 500 points, with wired network, no edge computing needs: GTE-3000\n- 500 to 3000 points, no network cables on site, requires 4G uplink: GTE-3000S\n- More than 3000 points, requires edge inference or CNC device connection: GTE-3000Pro\n\nThe point configuration format of all three devices is fully compatible. When upgrading from GTE-3000 to GTE-3000Pro later, export the configuration and import it directly, without needing to re-enter the points.',0.031010,5,'BM25 search+Vector search','2026-09-05 15:14:07');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (120,366,461,134,'GTE-3000Pro also supports deploying custom containers, which requires signing a technical cooperation agreement for permission to be granted by us',0.030077,6,'BM25 search+Vector search','2026-09-05 15:14:07');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (121,366,160,125,'.\n\nMain functional areas:\n\n- Runtime Monitoring: CPU, memory, storage usage, real-time status of each collection group\n- Device Management: Adding, deleting, modifying, and querying field devices and data points, supporting Excel batch import\n- Data Forwarding: Configuration and topic mapping for northbound connections\n- Edge Rules: Rule writing and debugging\n- System Maintenance: Firmware upgrades, configuration import/export, log download, time synchronization\n\nExported configuration files are in an encrypted .glcfg format. During import, the model and version are validated, and cross-model imports are rejected. Configurations from GTE-3000 can be imported into GTE-3000S, but not vice versa, due to the possibility of exceeding the lower model\'s data point limit with higher model data points.\n\n## 8. Security Mechanism\n\nThe device defaults to disabling Telnet and FTP, only opening HTTPS and SSH. SSH default port is 22, which can be modified in the system maintenance page.\n\nSupports three levels of user roles: administrators can perform all operations; maintenance personnel can view monitoring, download logs, and restart collection tasks, but cannot modify point configuration; visitors have read-only access.\n\nFirmware packages are signed by Northline Industrial Systems, and signature verification is performed during device upgrades. If the signature is invalid, the upgrade is rejected and the original firmware is retained. The upgrade process takes about 3 to 5 minutes, during which data collection is interrupted. After upgrade, the device automatically restarts and restores the original configuration',0.029857,7,'BM25 search+Vector search','2026-09-05 15:14:07');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (122,366,174,128,'.\n\nII. Current Maintenance Versions\n\n3.2.14-r5   Stable version, released in September 2024, recommended for production environments\n3.3.6-r2    Feature version, released in December 2024, supports 5G dual SIM dual standby and MQTT 5.0\n2.9.20-r8   Maintenance version, only fixes critical defects, maintenance stops on December 31, 2025\n\nIII. Major Changes in 3.3.6\n\nNew Features:\n1. MQTT 5.0 support, supports shared subscriptions and topic aliases, reducing message overhead by about 15% in long connection scenarios\n2. GTE-3000S and GTE-3000Pro support 5G dual SIM dual standby, automatically switching to the backup SIM within 30 seconds when the main SIM fails\n3. Collection groups support importing and exporting to Excel, including fields such as point name, register address, data type, and scaling coefficient\n4. Web interface adds a \"Communication Quality\" panel, displaying response time and timeout rate for each southbound device\n5. Edge rules support window functions, allowing calculation of 5-minute sliding averages\n\nBug Fixes:\n1. Fixed the occasional frame loss issue with RS485 at 115200bps over long periods, caused by the serial port driver buffer not being cleared in high load conditions\n2. Fixed the data order disorder issue during disconnection recovery, with the recovery queue now strictly sorted by timestamp\n3. | Configuration file import fixes DO |',0.014925,8,'BM25 search','2026-09-05 15:14:07');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (123,368,233,133,'. The warranty period is based on the manufacturing date indicated on the equipment nameplate.\n(ii) A maximum of 3 extensions for customers who can provide valid purchase vouchers, based on the date of purchase\nMonth.\nThree. The warranty period for accessories such as power adapters, antennas, terminals, rail clips, etc., is 12 months.\nFour. Spare parts purchased separately are warranted for 6 months from the date of receipt; spare parts replaced during whole machine repair follow the remaining warranty period of the whole machine, with a minimum of 3 months if less than 3 months remain.\nFive. If a fault is not resolved after two repairs within the warranty period, the customer may request a replacement. The warranty period of the new equipment is calculated based on the remaining warranty period of the original equipment, with a minimum of 3 months if less than 3 months remain.\nSix. Free warranty scope\nDuring the warranty period, functional faults caused by design, material, or manufacturing process defects are covered by free repair or replacement, including but not limited to: motherboard component failure, interface soldering issues, power module anomalies, wireless module non-recognition, and storage chip write failure.\nMonthly calculation',0.689955,1,'Agentic search','2026-09-05 15:15:03');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (124,368,446,134,'. The warranty period for accessories such as power adapters and antennas is 12 months. The warranty period is based on the manufacturing date on the equipment\'s nameplate. If the customer can provide valid purchase proof, the warranty period can be extended from the purchase date, with a maximum extension of 3 months',0.684115,2,'Agentic search','2026-09-05 15:15:03');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (125,368,273,135,'. After the warranty period, customers can purchase and replace the motherboard themselves, but the equipment will no longer be covered by the full warranty, and only the motherboard itself will have a 6-month warranty\n\nQ: Does the spare part have a warranty?\nA: Yes. Spare parts purchased separately are warranted for 6 months from the date of receipt. Spare parts replaced during a full system repair will carry the remaining warranty period of the system, with any remaining period less than 3 months counted as 3 months.',0.646740,3,'Agentic search','2026-09-05 15:15:03');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (126,368,236,133,'.\nIII. MAINTENANCE SERVICES: COMPLETE EXCESSING AND READY TO BE CONTINUED AND SUBJECT IN FIVE WORKING DAYS\nThe cost of transportation is borne by the company during the guarantee period; outside the guarantee period, the customer bears the cost of sending.\nThe company bears the cost of return freight.\nIV. Home service: for customers purchasing door-to-door packages or single purchase 50\nOn the project client. The major service cities arrives at the site within 24 hours, and the other municipalities within 48 hours.\nOn arrival, the two sides in the remote areas agree otherwise.\nArticle 6 On standby\nCustomers who have signed an annual service agreement can apply for a spare machine loan during the device repair period, with a maximum loan period of 15 days. The spare machine will be of the same model or a higher model, with configuration assistance provided by our engineers.\nLongest 15 days. The spare machine is of the same model or higher model, configuration is imported by our engineers',0.610097,4,'Agentic search','2026-09-05 15:15:03');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (127,368,234,133,'.\nOne. Beyond the warranty period.\nTwo. Improper use as per the product manual, such as input voltage exceeding the DC 9V to 36V range, long-term environmental temperature exceeding 70°C, or communication board damage due to lack of grounding.\nThree. Customer disassembly, modification, or damage to the seal.\nFour. Damage caused by force majeure such as water immersion, fire, lightning, earthquake, or power surge.\nFive. Obvious mechanical damage to the housing, such as structural deformation from dropping.\nSix. Use of firmware not released by Northline Industrial Systems or installation of unauthorized third-party software leading to faults.\nSeven. Normal use resulting in appearance wear or fading of printing that does not affect functionality, which is not covered by warranty and does not affect warranty of other components.\n\n[Page 2]\nEight. Service response time\nOne. Service hotline 416-555-0147, available from 8:30 to 20:00 on weekdays, and 9:00 to 18:00 on holidays.\nIV. Damage caused by irresistible forces such as water immersion, fire, lightning, earthquake, and power surge',0.603640,5,'Agentic search','2026-09-05 15:15:03');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (146,454,267,135,'. We will complete the appearance and function inspection within 3 working days after receiving the goods\n5. Refund is processed within 5 working days after the inspection passes, and the refund is returned via the original payment method\n\nIf the inspection reveals that the equipment has been damaged by human factors, the return application will be canceled, and the equipment will be sent back to the customer, with the shipping costs borne by the customer',0.643712,1,'Agentic search','2026-09-05 15:49:30');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (147,454,265,135,'.\n3. If the delivered model and configuration do not match the contract and the customer does not accept replacement, the equipment can be returned, and all costs will be borne by the company',0.545196,2,'Agentic search','2026-09-05 15:49:30');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (148,454,266,135,'.\n\n(II) Not Eligible for Return\n\n1. More Than 15 Days After Delivery\n2. The Equipment Has Been Put into Use and Has Caused Wear, Scratches, or Terminal Deformation\n3. Seal Broken or Self-Disassembly\n4. Devices with Custom Firmware or Custom Hardware Configuration\n5. Devices Converted from Trial to Purchase (Trial Period Is the Acceptance Period)\n6. Devices for promotion, clearance, and special price sales of sample units\n\n(3) Return Process\n\n1. Customers submit a return application, noting the device serial number, purchase order number, and reason for return, along with on-site photos\n2. Customer Service Center reviews and responds within 2 working days\n3. After approval, customers return the device, with a copy of the return application attached inside the packaging\n4. We complete the appearance and function inspection within 3 working days after receiving the device\n5. Testing',0.537210,3,'Agentic search','2026-09-05 15:49:30');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (149,454,270,135,'.\n\n(3) Exchange Process\n\n1. Submit an exchange application, noting the original device serial number and target model\n2. After approval, the company will first send the new device (the customer must provide a deposit or sign a Device Return Commitment Letter)\n3. The customer returns the original device within 10 working days after receiving the new device\n4. After inspecting the original device and confirming no human damage, the deposit is refunded or the commitment letter is released\n5. If the original device is not returned on time, a charge will be issued based on the original price of the new device\n\nSeven. Packaging Requirements for Repairs and Returns\n\n1. Use the original factory packaging box; if unavailable, use a hard cardboard box with no less than 5 layers of corrugated paper\n2. Fill the device around with shock-absorbing material of no less than 3 centimeters thickness\n3. Small parts such as terminals and antennas should be individually bagged to avoid scratching the motherboard during transportation',0.520610,4,'Agentic search','2026-09-05 15:49:30');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (150,454,272,135,'.\n\nEight. Common Issues\n\nQ: Where can I find the device serial number?\nA: The serial number is printed on the device\'s side label, with the format GL3000-YYWW-XXXXX, where YY represents the last two digits of the manufacturing year and WW represents the manufacturing week. It can also be viewed at the top of the Web interface\'s [Operation Monitoring] page\n\nQ: How to handle the invoice when returning?\nA: The original copy of the issued VAT special invoice must be returned. We will process the refund after receiving the original invoice. If the invoice has been authenticated and claimed for tax deduction, the customer must issue a red invoice information form\n\nQ: Can I just replace the motherboard and repair it myself?\nAnswer: Disassembling the equipment during the warranty period will result in the loss of warranty eligibility',0.491770,5,'Agentic search','2026-09-05 15:49:30');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (160,502,157,125,'. DO is often used for connecting sound alarms to export signals when collecting breaks or thresholds.\n\n## 4. Protocol Support\n\nProtocols supported by the device facing field equipment:\n\n- Modbus RTU / Modbus TCP\n- OPC UA Client\n- Siemens S7(S7-200 Smart / S7-1200 / S7-1500)\n- Mitsubishi MC Protocol (3E Frame)\n- Omron FINS\n- Mitsubishi FX Series Programming Port Protocol\n- CNC Equipment\'s FOCAS Protocol (Only supported by GTE-3000Pro)\n\nProtocols supported by the device facing upper-level systems:\n\n- MQTT 3.1.1 / MQTT 5.0, supporting TLS encryption and mutual certificate authentication\n- HTTP / HTTPS Active Reporting\n- OPC UA Server\n- Standard access to AWS IoT and Azure IoT platforms\n\nGTE-3000 can be configured with up to 2000 data points, GTE-3000S with 5000, and GTE-3000Pro with 20000. New data points beyond the point limit will be rejected, and the web configuration page will prompt \"Number of data points exceeds the current model limit\"',0.032018,1,'BM25 search+Vector search','2026-09-05 16:27:11');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (161,502,158,125,'New data points beyond the point limit will be rejected, and the web configuration page will prompt \"Number of data points exceeds the current model limit\"\n\n## 5. Data Collection and Reporting Mechanism\n\nCollection tasks are organized by \"Collection Groups.\" A collection group includes several data points, a collection cycle, and a reporting strategy. The minimum collection cycle is 100ms, maximum 3600s. Reporting strategies include three types:\n\n**Periodic Reporting**: Pack the latest value and report it at fixed intervals, independent of the collection cycle configuration. Suitable for trend data, such as temperature, current.\n\n**Change Reporting**: Report only when the value changes beyond the set deadband threshold. Suitable for state data, significantly reducing traffic. Deadband threshold supports absolute value and percentage formats.\n\n**Hybrid Reporting**: Immediately report upon change, while also reporting once at a longer heartbeat cycle to ensure the upper system receives the latest value even if it missed the change event. Recommended for production environments.\n\nData is stored in local cache when the network is down. GTE-3000 has a cache capacity of 100,000 entries, GTE-3000S has 500,000, and GTE-3000Pro has 5,000,000. After network recovery, data is resent in chronological order, with a default transmission rate limit of 200 entries per second to avoid overwhelming the upper system. When the cache is full, the oldest data is discarded on a first-in-first-out basis.\n\n## 6. Edge Computing\n\nGTE-3000Pro supports running edge rules and lightweight models on the device',0.032002,2,'BM25 search+Vector search','2026-09-05 16:27:11');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (162,502,156,125,'LAN2 is default as business port, with factory configuration as DHCP client. LAN3 and LAN4 of GTE-3000S and GTE-3000Pro can be configured as switch ports, cascading downstream devices\n\nWhen the management port IP is forgotten, hold the RESET button for more than 10 seconds to restore factory settings, returning the management port IP to 192.168.1.10. Restoring factory settings will clear all collected point configurations; make sure to export the configuration file before operation.\n\n### 3.3 Serial Ports\n\nRS485 uses a 2-pin terminal with A and B lines. Serial port parameters support 1200 ~ 115200bps, default 9600bps, 8 data bits, 1 stop bit, no parity check. A maximum of 32 slave devices can be connected on the same 485 bus, with 120Ω terminal resistors required at both ends of the bus. GTE-3000S and GTE-3000Pro have built-in terminal resistors that can be enabled via a dip switch.\n\n### 3.4 Digital Input/Output\n\nGTE-3000Pro provides 4 routes DI and 2 paths DO. DI is inputted for dry interfaces, which are relay output, contact capacity 30VDC/2A. DO is often used to connect sound alarms and to export signals when collecting breaks or threshold limits',0.031754,3,'BM25 search+Vector search','2026-09-05 16:27:11');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (163,502,161,125,'The upgrade process takes about 3 to 5 minutes, during which data collection is interrupted. After upgrade, the device automatically restarts and restores the original configuration\n\n## 9. Typical Deployment Methods\n\n**Single Machine Deployment**: One GTE-3000 connects to a PLC and instruments on a production line, and connects to the workshop switch via LAN2, with data reporting to the plant-level MES.\n\n**Dual Machine Hot Standby**: Two GTE-3000S units are interconnected via a heartbeat line. The standby unit takes over within 5 seconds if the main unit fails. Point configuration is automatically synchronized from the main unit to the standby unit. Hot standby requires both devices to have the same model and firmware version.\n\n**Cascade Deployment**: At the workshop level, multiple GTE-3000 units collect data nearby, and the data is aggregated to a GTE-3000Pro for edge computing and unified cloud upload, reducing the number of public network connections.\n\n## 10. Selection Recommendations\n\n- Less than 500 points, with wired network, no edge computing needs: GTE-3000\n- 500 to 3000 points, no network cables on site, requires 4G uplink: GTE-3000S\n- More than 3000 points, requires edge inference or CNC device connection: GTE-3000Pro\n\nThe point configuration format of all three devices is fully compatible. When upgrading from GTE-3000 to GTE-3000Pro later, export the configuration and import it directly, without needing to re-enter the points.',0.031258,4,'BM25 search+Vector search','2026-09-05 16:27:11');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (164,502,461,134,'GTE-3000Pro also supports deploying custom containers, which requires signing a technical cooperation agreement for permission to be granted by us',0.030090,5,'BM25 search+Vector search','2026-09-05 16:27:11');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (165,502,160,125,'.\n\nMain functional areas:\n\n- Runtime Monitoring: CPU, memory, storage usage, real-time status of each collection group\n- Device Management: Adding, deleting, modifying, and querying field devices and data points, supporting Excel batch import\n- Data Forwarding: Configuration and topic mapping for northbound connections\n- Edge Rules: Rule writing and debugging\n- System Maintenance: Firmware upgrades, configuration import/export, log download, time synchronization\n\nExported configuration files are in an encrypted .glcfg format. During import, the model and version are validated, and cross-model imports are rejected. Configurations from GTE-3000 can be imported into GTE-3000S, but not vice versa, due to the possibility of exceeding the lower model\'s data point limit with higher model data points.\n\n## 8. Security Mechanism\n\nThe device defaults to disabling Telnet and FTP, only opening HTTPS and SSH. SSH default port is 22, which can be modified in the system maintenance page.\n\nSupports three levels of user roles: administrators can perform all operations; maintenance personnel can view monitoring, download logs, and restart collection tasks, but cannot modify point configuration; visitors have read-only access.\n\nFirmware packages are signed by Northline Industrial Systems, and signature verification is performed during device upgrades. If the signature is invalid, the upgrade is rejected and the original firmware is retained. The upgrade process takes about 3 to 5 minutes, during which data collection is interrupted. After upgrade, the device automatically restarts and restores the original configuration',0.030077,6,'BM25 search+Vector search','2026-09-05 16:27:11');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (166,502,153,125,'# GTE-3000 Series Industrial Smart Gateway Technical Manual\n\nDocument Number: GL-PRD-2024-017\nVersion: V3.2\nModels covered: GTE-3000, GTE-3000S, and GTE-3000Pro\nPublished by the Product Department, Northline Industrial Systems Inc.\n\n## 1. Product Overview\n\nGTE-3000 Series is a industrial intelligent gateway launched by Northline Industrial Systems for discrete manufacturing and process industries. It is deployed between production line equipment and upper-level systems, responsible for protocol conversion, edge computing, and data cloud upload. The device adopts a fanless aluminum alloy casing design, supporting DIN rail mounting and wall mounting',0.029631,7,'BM25 search+Vector search','2026-09-05 16:27:11');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (167,502,154,125,'.\n\nThere are three models in the series, with consistent hardware platforms, and differences mainly lie in computing power, number of interfaces, and wireless capabilities:\n\n| Model | Processor | Memory | Storage | Ethernet Port | Serial Port | Wireless | Typical Power Consumption |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| GTE-3000 | Quad-core 1.2GHz | 2GB | 8GB eMMC | 2 × Gigabit | 2 × RS485 | None | 6.5W |\n| GTE-3000S | Quad-core 1.2GHz | 4GB | 16GB eMMC | 4 × Gigabit | 4 × RS485/RS232 | 4G Full Network Coverage | 9.2W |\n| GTE-3000Pro | Eight-core 1.8GHz | 8GB | 64GB eMMC | 4 × Gigabit | 4 × RS485/RS232 | 5G + Wi-Fi 6 | 15.8W |\n\nGTE-3000 is the basic model, suitable for small-scale data collection on a single production line; GTE-3000S adds 4G uplink and more serial ports, suitable for workshops without wired networks; GTE-3000Pro has local inference capabilities, allowing lightweight vision detection models to run at the edge',0.016393,8,'Vector search','2026-09-05 16:27:11');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (168,504,267,135,'. We will complete the appearance and function inspection within 3 working days after receiving the goods\n5. Refund is processed within 5 working days after the inspection passes, and the refund is returned via the original payment method\n\nIf the inspection reveals that the equipment has been damaged by human factors, the return application will be canceled, and the equipment will be sent back to the customer, with the shipping costs borne by the customer',0.650795,1,'Agentic search','2026-09-05 16:32:06');
