INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (188,510,460,134,'The certification certificate can be obtained in electronic format from the sales manager\n\n### Q21: Is the old model GTE-2000 still available for purchase?\n\nGTE-2000 was discontinued in December 2023. Currently, only spare parts and repair support are provided, with support until December 2026. New projects are recommended to directly select the GTE-3000 series. Point configuration files can be migrated from GTE-2000 to GTE-3000 via conversion tools.\n\n### Q22: Can secondary development interfaces be provided?\n\nYes. The device provides two ways to connect: RESTful API and OPC UA Server. The API documentation can be downloaded from the official website [Developer] section',0.015385,8,'Vector search','2026-09-05 16:38:27');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (198,560,456,134,'If the status is \"Connected\", it indicates that the network and authentication are normal, and the issue is likely in topic mapping or platform-side subscription; if the status is \"Reconnecting\", it indicates network or certificate issues. Check if the device can ping the platform domain name, whether the certificate has expired, and whether the system time is accurate. System time deviation exceeding 5 minutes can cause TLS handshake failure\n\n## IV. Faults and Alarms\n\n### Q14: What does the error code ERR-5021 mean?\n\nERR-5021 indicates incompatibility between point configuration and the protocol stack, commonly occurring after cross-major version firmware upgrades. The solution is to roll back to the firmware version before the upgrade, and follow the instructions in the [Firmware Upgrade and Version Release Notes] to first upgrade to the transitional version before the target version.\n\n### Q15: Why does the device frequently restart?\n\nThe three most common reasons are:\n\n1. Yes. Download the Excel template from [Device Management] → [Point Management], fill in the point name, register address, data type, scaling coefficient, unit, and other fields according to the template, and import it. Single import is limited to no more than 5000 rows, and batch imports are required if exceeded',0.829305,1,'Agentic search','2026-09-05 17:27:48');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (199,560,450,134,'. The spare unit is of the same model or a higher model. The configuration during the borrowing period will be assisted by our engineers. A daily usage fee of 1% of the original equipment price will be charged if the equipment is not returned on time\n\n## III. Installation and Commissioning\n\n### Q10: What should I do if I forget the device management port IP?\n\nLong press the RESET button on the equipment panel for more than 10 seconds to restore the equipment to factory settings. The management port IP will be restored to 192.168.1.10, with the default account admin and default password Gl@2024. Restoring to factory settings will clear all point configuration. Please try other methods to recover the equipment first, such as using a network scanning tool to find the host with the MAC prefix 8C:1F:64 in the network segment',0.603541,2,'Agentic search','2026-09-05 17:27:48');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (200,560,455,134,'Q12: After data is uploaded to the cloud, the platform does not receive it. Where to start checking\n\n### Q13: Can point configurations be imported in bulk?\n\nCheck the connection status on the [Data Forwarding] page',0.595112,3,'Agentic search','2026-09-05 17:27:48');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (201,560,453,134,'GTE-3000 series product technical manual\n\n### GTE series on-site installation and maintenance operation guide',0.580170,4,'Agentic search','2026-09-05 17:27:48');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (202,560,448,134,'?\n\nChoose any of the following three methods:\n\n1. Call the service hotline at 416-555-0147, from 8:30 to 20:30 on weekdays, and 9:00 to 18:00 on holidays\n2. Submit an online service ticket on the Northline Industrial Systems official website under the [Service Support] section\n3. Contact the assigned sales manager or after-sales engineer\n\nWhen reporting a repair, please provide the equipment serial number (SN), description of the fault phenomenon, time of fault occurrence, on-site photos or log files',0.576325,5,'Agentic search','2026-09-05 17:27:48');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (212,608,267,135,'. We will complete the appearance and function inspection within 3 working days after receiving the goods\n5. Refund is processed within 5 working days after the inspection passes, and the refund is returned via the original payment method\n\nIf the inspection reveals that the equipment has been damaged by human factors, the return application will be canceled, and the equipment will be sent back to the customer, with the shipping costs borne by the customer',0.660440,1,'Agentic search','2026-09-05 17:41:41');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (213,608,265,135,'.\n3. If the delivered model and configuration do not match the contract and the customer does not accept replacement, the equipment can be returned, and all costs will be borne by the company',0.586382,2,'Agentic search','2026-09-05 17:41:41');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (214,608,266,135,'.\n\n(II) Not Eligible for Return\n\n1. More Than 15 Days After Delivery\n2. The Equipment Has Been Put into Use and Has Caused Wear, Scratches, or Terminal Deformation\n3. Seal Broken or Self-Disassembly\n4. Devices with Custom Firmware or Custom Hardware Configuration\n5. Devices Converted from Trial to Purchase (Trial Period Is the Acceptance Period)\n6. Devices for promotion, clearance, and special price sales of sample units\n\n(3) Return Process\n\n1. Customers submit a return application, noting the device serial number, purchase order number, and reason for return, along with on-site photos\n2. Customer Service Center reviews and responds within 2 working days\n3. After approval, customers return the device, with a copy of the return application attached inside the packaging\n4. We complete the appearance and function inspection within 3 working days after receiving the device\n5. Testing',0.583063,3,'Agentic search','2026-09-05 17:41:41');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (215,608,264,135,'. During the support period, spare parts will be supplied based on existing inventory. If the inventory is exhausted, alternative solutions will be provided, including discounted trade-in or migration to the GTE-3000 series\n\nSpare Parts for Discontinued Models Are Not Acceptable for Returns.\n\nV. Return Policy\n\n(I) Eligible for Return\n\n1. Within 7 Days of Delivery, If the Equipment Is Unopened, Packaging Intact, and Accessories Complete, and the Customer Requests a Return for Reasons Related to the Customer, a No-Reason Return Can Be Applied, with the Customer Bearing Round-Trip Freight, and the Company Not Charging Depreciation Fees.\n2. If the equipment is confirmed to have quality issues and cannot be resolved through repair within 15 days of delivery, it can be returned. The company will cover the round-trip shipping costs, and the full payment will be refunded',0.560201,4,'Agentic search','2026-09-05 17:41:41');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (216,608,240,133,'.\nAnnex XII\nThis provision is explained by the Client Service Centre and has been in effect since its entry into force.\nThe provision (GL-SVC-2022-002) was repealed at the same time.',0.542563,5,'Agentic search','2026-09-05 17:41:41');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (217,612,194,130,'Northline Industrial Systems Inc. Travel and Expense Reimbursement Policy\n\nDocument Number: GL-FIN-2024-004\n\nVersion: V3.5\n\nEffective Date: September 1, 2024\n\nResponsible Department: Finance Department\n\nChapter One General Provisions\n\nThis system is applicable to all employees of the company on official business, daily expense advances and various types of reimbursement operations.\n\nArticle 2: Reimbursement follows three principles: approval before expenditure, truthfulness, and compliance with documents. Expenses incurred without approval are not reimbursable by the company.\n\nChapter Two: Business Travel Management\n\nArticle 3: Before traveling, an official travel application must be submitted via the OA system, specifying the purpose of the trip, destination, start and end dates, accompanying personnel, and estimated expenses. Approval is required before booking tickets. Emergency travel may proceed first, but an application must be submitted within one working day after departure.\n\nArticle 4: Travel approval authority: within 3 days, approved by the department head; 3 to 7 days, approved by the vice president in charge; more than 7 days or international travel, approved by the general manager.\n\nArticle 5: Standards for transportation:\n\nFor regular employees, an upgrade is allowed if the one-way flight duration exceeds 3 hours or the train journey exceeds 6 hours, requiring approval from the deputy general manager in charge.\n\nArticle 6: Accommodation Standards (per person per night, inclusive of tax):\n\nExcess accommodation standards require prior application and explanation of reasons. Any post-trip reimbursement will be based on the standard maximum, with the difference to be covered by the individual. For two employees of the same gender traveling together, it is encouraged to share a standard room, with savings of 50 CAD per person per night provided as a subsidy.\n\nArticle 7: Travel Allowance (per person per day):\n\nSubsidy is not issued for round-trip travel on the same day that is less than 8 hours; if meals are arranged by the client or partner, the meal allowance for that day is not issued. If an employee is continuously stationed at the client site for 5 working days, an additional site stay allowance is issued according to Article 17 of the employee handbook.\n\nChapter Three: Expense Reimbursement\n\nArticle 8: Reimbursement Deadline: Submit the reimbursement form within 30 days after the expense occurs. For expenses spanning across years, the latest submission is by January 15th of the following year. Claims submitted after the deadline will not be processed.\n\nArticle 9: Document Requirements: The invoice name must be the full company name, and the taxpayer identification number must be accurate. Itemized receipts must identify the supplier, transaction date, amount, and applicable taxes. Meal and accommodation expenses must be accompanied by consumption details. Taxi fares must be supported by a trip itinerary, not just payment screenshots.\n\nArticle 10: Reimbursement Approval Authority:\n\nArticle 11: Payment Cycle: Fixed payment dates are the 10th and 25th of each month. Reimbursement forms that complete financial review within 3 working days before the payment date are included in the current period\'s payment; otherwise, they are postponed to the next period.\n\nArticle 12: Loan Management: Single prepayment loans shall not exceed 80% of the estimated expenses. The loan must be settled within 10 working days after the business trip. No new loan can be issued if the previous loan has not been settled.\n\nChapter Four: Violation Handling\n\nArticle 13: Full reimbursement will be reclaimed for fake invoices, false expense reporting, and splitting invoices to bypass approval. Such actions will be treated as serious violations according to Article 30 of the employee handbook.\n\nArticle 14 The Treasury conducts quarterly spot checks of reimbursement documents, which are not less than 10 per cent and the results are reported to the General Manager.\n\nChapter Five: Supplementary Provisions\n\nArticle 15: This regulation is interpreted by the Finance Department and will be implemented from the effective date.\n\n| Role | Air travel | Rail travel | Local transportation |\n| --- | --- | --- | --- |\n| General manager and above | Business class | Business class | Actual expenses |\n| Director or responsible vice president | Economy class | First class | Actual expenses |\n| Manager or supervisor | Economy class | Second class | Daily',0.466713,1,'BM25 search+Vector search→Rerank→Parent chunk expansion','2026-09-05 17:42:47');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (218,614,162,126,'GTE Series Gateway Field Installation and Maintenance Guide\n\nDocument Number: GL-OPS-2024-009\n\nVersion: V2.6\n\nModels covered: GTE-3000, GTE-3000S, and GTE-3000Pro\n\nPrepared by: Technical Service Department\n\n1. Preparation Before Operation\n\nBefore on-site operation, three confirmations must be completed: first, confirm that the ambient temperature at the installation location does not exceed 60°C long-term, and is away from strong interference sources such as inverters and large power contactors; second, confirm that the on-site power supply is DC 9V to 36V, and an independent circuit breaker is reserved; third, confirm the network conditions, wired access requires pre-laid network cables, and 4G/5G access requires confirmation that the signal strength on-site is no less than -95dBm.\n\nList of Tools:\n\n2. Installation steps\n\n1. Disconnect the on-site power supply, confirm the power indicator light is off before proceeding with wiring work.\n\n2. Insert the gateway\'s snap hook into the DIN rail, first hang the side then push down to secure, you can hear the snap hook in place sound; for wall mounting, use M4 screws to fix the four corners.\n\n3. Connect power supply: the 3-pin terminal from left to right is V+, V-, PE, PE must be connected to the grounding busbar of the cabinet, grounding resistance should not exceed 4Ω.\n\n4. Connecting to RS485: A connects to A, B connects to B, 120Ω terminal resistor is enabled at both ends of the bus, and the shield is grounded at one end',0.032522,1,'BM25 search+Vector search','2026-09-05 17:43:35');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (219,614,153,125,'# GTE-3000 Series Industrial Smart Gateway Technical Manual\n\nDocument Number: GL-PRD-2024-017\nVersion: V3.2\nModels covered: GTE-3000, GTE-3000S, and GTE-3000Pro\nPublished by the Product Department, Northline Industrial Systems Inc.\n\n## 1. Product Overview\n\nGTE-3000 Series is a industrial intelligent gateway launched by Northline Industrial Systems for discrete manufacturing and process industries. It is deployed between production line equipment and upper-level systems, responsible for protocol conversion, edge computing, and data cloud upload. The device adopts a fanless aluminum alloy casing design, supporting DIN rail mounting and wall mounting',0.032266,2,'BM25 search+Vector search','2026-09-05 17:43:35');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (220,614,161,125,'The upgrade process takes about 3 to 5 minutes, during which data collection is interrupted. After upgrade, the device automatically restarts and restores the original configuration\n\n## 9. Typical Deployment Methods\n\n**Single Machine Deployment**: One GTE-3000 connects to a PLC and instruments on a production line, and connects to the workshop switch via LAN2, with data reporting to the plant-level MES.\n\n**Dual Machine Hot Standby**: Two GTE-3000S units are interconnected via a heartbeat line. The standby unit takes over within 5 seconds if the main unit fails. Point configuration is automatically synchronized from the main unit to the standby unit. Hot standby requires both devices to have the same model and firmware version.\n\n**Cascade Deployment**: At the workshop level, multiple GTE-3000 units collect data nearby, and the data is aggregated to a GTE-3000Pro for edge computing and unified cloud upload, reducing the number of public network connections.\n\n## 10. Selection Recommendations\n\n- Less than 500 points, with wired network, no edge computing needs: GTE-3000\n- 500 to 3000 points, no network cables on site, requires 4G uplink: GTE-3000S\n- More than 3000 points, requires edge inference or CNC device connection: GTE-3000Pro\n\nThe point configuration format of all three devices is fully compatible. When upgrading from GTE-3000 to GTE-3000Pro later, export the configuration and import it directly, without needing to re-enter the points.',0.031054,3,'BM25 search+Vector search','2026-09-05 17:43:35');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (221,614,261,135,'.\n\nII. Spare Parts Catalog and Pricing\n\nCommon Spare Parts and Reference Prices (Including Tax, Unit: CAD):\n\nGTE-3000 Mainboard                    1280\nGTE-3000S Mainboard                   1860\nGTE-3000Pro Mainboard                 3450\n24V/2A Industrial Power Adapter              120\n3-Pin Power Phoenix Terminal                    15\nSerial Terminal (5-Pin)                    18\nDIN Rail Clip',0.029857,4,'BM25 search+Vector search','2026-09-05 17:43:36');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (222,614,457,134,'Single import is limited to no more than 5000 rows, and batch imports are required if exceeded. The system will perform format validation before import, and rows that fail validation will be highlighted in red with the reason, and re-import after correction\n2. High ambient temperature. Long-term temperatures above 60°C will trigger a protection restart. Check if the installation location is near a heat source and if the cabinet has proper ventilation.\n3. High memory usage by edge rules or models. When the GTE-3000Pro runs more than three models simultaneously, it may trigger memory protection. Reduce the number of models.\n\n### Q16: Will data be lost during network disconnection?\n\nUnstable power supply',0.015873,5,'BM25 search','2026-09-05 17:43:36');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (223,614,156,125,'LAN2 is default as business port, with factory configuration as DHCP client. LAN3 and LAN4 of GTE-3000S and GTE-3000Pro can be configured as switch ports, cascading downstream devices\n\nWhen the management port IP is forgotten, hold the RESET button for more than 10 seconds to restore factory settings, returning the management port IP to 192.168.1.10. Restoring factory settings will clear all collected point configurations; make sure to export the configuration file before operation.\n\n### 3.3 Serial Ports\n\nRS485 uses a 2-pin terminal with A and B lines. Serial port parameters support 1200 ~ 115200bps, default 9600bps, 8 data bits, 1 stop bit, no parity check. A maximum of 32 slave devices can be connected on the same 485 bus, with 120Ω terminal resistors required at both ends of the bus. GTE-3000S and GTE-3000Pro have built-in terminal resistors that can be enabled via a dip switch.\n\n### 3.4 Digital Input/Output\n\nGTE-3000Pro provides 4 routes DI and 2 paths DO. DI is inputted for dry interfaces, which are relay output, contact capacity 30VDC/2A. DO is often used to connect sound alarms and to export signals when collecting breaks or threshold limits',0.015625,6,'Vector search','2026-09-05 17:43:36');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (224,614,163,126,'.\n\n5. Connect Ethernet: LAN1 is the management port, LAN2 is the business port, after the network cable is done, use the tester to confirm the wiring order is T568B.\n\n6. Install the antenna for the wireless model, the antenna should be extended as much as possible outside the metal cabinet, installation inside the cabinet will cause signal attenuation of more than 10dB.\n\n7. Power on, observe the indicator lights: PWR constantly lit indicates normal power supply, SYS flashing once per second indicates normal system operation, COM flashing indicates data transmission and reception on the serial port.\n\n3. Commissioning and acceptance\n\nLaptop network port configured as 192.168.1.100/24, access https://192.168.1.10 via browser to log in to the Web interface, default account admin, default password Gl@2024, password must be changed upon first login.\n\nComplete sequentially: change the management port IP to the planned on-site address, configure the business port network, add southbound devices and points, configure northbound MQTT connection, start the collection group, confirm the status of each collection group is running on the operation monitoring page.\n\nAcceptance criteria:\n\n4. Daily maintenance\n\nMonthly maintenance: Check indicator light status, check if CPU and memory usage on the Web interface are consistently above 80%, check if remaining storage space is below 20%, export and archive operational logs.\n\nQualitative maintenance: clean dust on the device surface and heat sink, retighten power and serial port terminals, check if system time deviation exceeds 1 minute, and export a complete configuration file backup',0.015625,7,'BM25 search','2026-09-05 17:43:36');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (225,614,461,134,'GTE-3000Pro also supports deploying custom containers, which requires signing a technical cooperation agreement for permission to be granted by us',0.015385,8,'Vector search','2026-09-05 17:43:36');
