INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (235,620,267,135,'. We will complete the appearance and function inspection within 3 working days after receiving the goods\n5. Refund is processed within 5 working days after the inspection passes, and the refund is returned via the original payment method\n\nIf the inspection reveals that the equipment has been damaged by human factors, the return application will be canceled, and the equipment will be sent back to the customer, with the shipping costs borne by the customer',0.628568,1,'Agentic search','2026-09-05 17:45:45');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (236,620,266,135,'.\n\n(II) Not Eligible for Return\n\n1. More Than 15 Days After Delivery\n2. The Equipment Has Been Put into Use and Has Caused Wear, Scratches, or Terminal Deformation\n3. Seal Broken or Self-Disassembly\n4. Devices with Custom Firmware or Custom Hardware Configuration\n5. Devices Converted from Trial to Purchase (Trial Period Is the Acceptance Period)\n6. Devices for promotion, clearance, and special price sales of sample units\n\n(3) Return Process\n\n1. Customers submit a return application, noting the device serial number, purchase order number, and reason for return, along with on-site photos\n2. Customer Service Center reviews and responds within 2 working days\n3. After approval, customers return the device, with a copy of the return application attached inside the packaging\n4. We complete the appearance and function inspection within 3 working days after receiving the device\n5. Testing',0.559441,2,'Agentic search','2026-09-05 17:45:45');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (237,620,265,135,'.\n3. If the delivered model and configuration do not match the contract and the customer does not accept replacement, the equipment can be returned, and all costs will be borne by the company',0.552811,3,'Agentic search','2026-09-05 17:45:45');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (238,620,270,135,'.\n\n(3) Exchange Process\n\n1. Submit an exchange application, noting the original device serial number and target model\n2. After approval, the company will first send the new device (the customer must provide a deposit or sign a Device Return Commitment Letter)\n3. The customer returns the original device within 10 working days after receiving the new device\n4. After inspecting the original device and confirming no human damage, the deposit is refunded or the commitment letter is released\n5. If the original device is not returned on time, a charge will be issued based on the original price of the new device\n\nSeven. Packaging Requirements for Repairs and Returns\n\n1. Use the original factory packaging box; if unavailable, use a hard cardboard box with no less than 5 layers of corrugated paper\n2. Fill the device around with shock-absorbing material of no less than 3 centimeters thickness\n3. Small parts such as terminals and antennas should be individually bagged to avoid scratching the motherboard during transportation',0.520743,4,'Agentic search','2026-09-05 17:45:45');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (239,620,264,135,'. During the support period, spare parts will be supplied based on existing inventory. If the inventory is exhausted, alternative solutions will be provided, including discounted trade-in or migration to the GTE-3000 series\n\nSpare Parts for Discontinued Models Are Not Acceptable for Returns.\n\nV. Return Policy\n\n(I) Eligible for Return\n\n1. Within 7 Days of Delivery, If the Equipment Is Unopened, Packaging Intact, and Accessories Complete, and the Customer Requests a Return for Reasons Related to the Customer, a No-Reason Return Can Be Applied, with the Customer Bearing Round-Trip Freight, and the Company Not Charging Depreciation Fees.\n2. If the equipment is confirmed to have quality issues and cannot be resolved through repair within 15 days of delivery, it can be returned. The company will cover the round-trip shipping costs, and the full payment will be refunded',0.520614,5,'Agentic search','2026-09-05 17:45:45');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (441,1488,169,127,'| S7 Connection Refused | Confirm the PLC\'s rack and slot configuration, confirm that the number of allowed connections has not been exhausted | Partial\n| ERR-5021 | Data point configuration incompatible with protocol stack | Critical | A field cannot be parsed while the data point configuration is loading. | Often follows a major firmware upgrade. Roll back and upgrade again through the intermediate release. | Yes |\n| ERR-5022 | Data point count exceeds model limit | Warning | The configured data point count exceeds the device model\'s limit. | Remove data points or upgrade to a higher model. Limits are 2,000 for GTE-3000, 5,000 for GTE-3000S, and 20,000 for GTE-3000Pro. | Partial |\n| ERR-6003 | MQTT authentication failed | Critical | The broker returns CONNACK error code 4 or 5. | Verify the username, password, and ClientID. Confirm that the device is enabled on the platform. | No |\n| ERR-6008 | TLS handshake failed | Critical | Certificate validation fails or clocks are out of sync. | Check certificate validity and the CA chain. Check whether the device clock is off by more than five minutes. | No |\n| ERR-6012 | Local cache full | Warning | While offline, the number of cached records reaches the device model\'s limit. | Restore network access. Once the cache is full, the oldest records are discarded first.',0.032787,1,'BM25 search+Vector search','2026-11-16 21:44:26');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (442,1488,158,125,'New data points beyond the point limit will be rejected, and the web configuration page will prompt \"Number of data points exceeds the current model limit\"\n\n## 5. Data Collection and Reporting Mechanism\n\nCollection tasks are organized by \"Collection Groups.\" A collection group includes several data points, a collection cycle, and a reporting strategy. The minimum collection cycle is 100ms, maximum 3600s. Reporting strategies include three types:\n\n**Periodic Reporting**: Pack the latest value and report it at fixed intervals, independent of the collection cycle configuration. Suitable for trend data, such as temperature, current.\n\n**Change Reporting**: Report only when the value changes beyond the set deadband threshold. Suitable for state data, significantly reducing traffic. Deadband threshold supports absolute value and percentage formats.\n\n**Hybrid Reporting**: Immediately report upon change, while also reporting once at a longer heartbeat cycle to ensure the upper system receives the latest value even if it missed the change event. Recommended for production environments.\n\nData is stored in local cache when the network is down. GTE-3000 has a cache capacity of 100,000 entries, GTE-3000S has 500,000, and GTE-3000Pro has 5,000,000. After network recovery, data is resent in chronological order, with a default transmission rate limit of 200 entries per second to avoid overwhelming the upper system. When the cache is full, the oldest data is discarded on a first-in-first-out basis.\n\n## 6. Edge Computing\n\nGTE-3000Pro supports running edge rules and lightweight models on the device',0.032002,2,'BM25 search+Vector search','2026-11-16 21:44:26');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (443,1488,161,125,'The upgrade process takes about 3 to 5 minutes, during which data collection is interrupted. After upgrade, the device automatically restarts and restores the original configuration\n\n## 9. Typical Deployment Methods\n\n**Single Machine Deployment**: One GTE-3000 connects to a PLC and instruments on a production line, and connects to the workshop switch via LAN2, with data reporting to the plant-level MES.\n\n**Dual Machine Hot Standby**: Two GTE-3000S units are interconnected via a heartbeat line. The standby unit takes over within 5 seconds if the main unit fails. Point configuration is automatically synchronized from the main unit to the standby unit. Hot standby requires both devices to have the same model and firmware version.\n\n**Cascade Deployment**: At the workshop level, multiple GTE-3000 units collect data nearby, and the data is aggregated to a GTE-3000Pro for edge computing and unified cloud upload, reducing the number of public network connections.\n\n## 10. Selection Recommendations\n\n- Less than 500 points, with wired network, no edge computing needs: GTE-3000\n- 500 to 3000 points, no network cables on site, requires 4G uplink: GTE-3000S\n- More than 3000 points, requires edge inference or CNC device connection: GTE-3000Pro\n\nThe point configuration format of all three devices is fully compatible. When upgrading from GTE-3000 to GTE-3000Pro later, export the configuration and import it directly, without needing to re-enter the points.',0.031498,3,'BM25 search+Vector search','2026-11-16 21:44:26');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (444,1488,156,125,'LAN2 is default as business port, with factory configuration as DHCP client. LAN3 and LAN4 of GTE-3000S and GTE-3000Pro can be configured as switch ports, cascading downstream devices\n\nWhen the management port IP is forgotten, hold the RESET button for more than 10 seconds to restore factory settings, returning the management port IP to 192.168.1.10. Restoring factory settings will clear all collected point configurations; make sure to export the configuration file before operation.\n\n### 3.3 Serial Ports\n\nRS485 uses a 2-pin terminal with A and B lines. Serial port parameters support 1200 ~ 115200bps, default 9600bps, 8 data bits, 1 stop bit, no parity check. A maximum of 32 slave devices can be connected on the same 485 bus, with 120Ω terminal resistors required at both ends of the bus. GTE-3000S and GTE-3000Pro have built-in terminal resistors that can be enabled via a dip switch.\n\n### 3.4 Digital Input/Output\n\nGTE-3000Pro provides 4 routes DI and 2 paths DO. DI is inputted for dry interfaces, which are relay output, contact capacity 30VDC/2A. DO is often used to connect sound alarms and to export signals when collecting breaks or threshold limits',0.029851,4,'BM25 search+Vector search','2026-11-16 21:44:26');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (445,1488,458,134,'Use a multimeter to measure the input voltage. When it is below 9V, the device will power off and restart. Prioritize checking the power adapter and line voltage drop\n\n## V. Account and Security\n\n### Q17: What should I do if I forget the Web management password?\n\nGuest password cannot be recovered, so the device must be reset via factory reset. Operator and visitor account passwords can be reset by the administrator via [System Maintenance]→[User Management]. It is recommended to retain at least two administrator accounts during deployment.\n\n### Q18: What security reinforcement measures does the device support?\n\nData will not be immediately lost. When the network is disconnected, data is stored in local cache. GTE-3000 can cache up to 100,000 entries, GTE-3000S up to 500,000 entries, and GTE-3000Pro up to 5,000,000 entries',0.029412,5,'BM25 search+Vector search','2026-11-16 21:44:26');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (446,1488,457,134,'Single import is limited to no more than 5000 rows, and batch imports are required if exceeded. The system will perform format validation before import, and rows that fail validation will be highlighted in red with the reason, and re-import after correction\n2. High ambient temperature. Long-term temperatures above 60°C will trigger a protection restart. Check if the installation location is near a heat source and if the cabinet has proper ventilation.\n3. High memory usage by edge rules or models. When the GTE-3000Pro runs more than three models simultaneously, it may trigger memory protection. Reduce the number of models.\n\n### Q16: Will data be lost during network disconnection?\n\nUnstable power supply',0.016129,6,'Vector search','2026-11-16 21:44:26');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (447,1488,157,125,'. DO is often used for connecting sound alarms to export signals when collecting breaks or thresholds.\n\n## 4. Protocol Support\n\nProtocols supported by the device facing field equipment:\n\n- Modbus RTU / Modbus TCP\n- OPC UA Client\n- Siemens S7(S7-200 Smart / S7-1200 / S7-1500)\n- Mitsubishi MC Protocol (3E Frame)\n- Omron FINS\n- Mitsubishi FX Series Programming Port Protocol\n- CNC Equipment\'s FOCAS Protocol (Only supported by GTE-3000Pro)\n\nProtocols supported by the device facing upper-level systems:\n\n- MQTT 3.1.1 / MQTT 5.0, supporting TLS encryption and mutual certificate authentication\n- HTTP / HTTPS Active Reporting\n- OPC UA Server\n- Standard access to AWS IoT and Azure IoT platforms\n\nGTE-3000 can be configured with up to 2000 data points, GTE-3000S with 5000, and GTE-3000Pro with 20000. New data points beyond the point limit will be rejected, and the web configuration page will prompt \"Number of data points exceeds the current model limit\"',0.015625,7,'BM25 search','2026-11-16 21:44:26');
INSERT INTO `message_reference` (`id`, `message_id`, `chunk_id`, `document_id`, `chunk_content`, `score`, `rank_no`, `retrieval_source`, `create_time`) VALUES (448,1488,453,134,'GTE-3000 series product technical manual\n\n### GTE series on-site installation and maintenance operation guide',0.015385,8,'Vector search','2026-11-16 21:44:26');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (1,'RAG_ANSWER','Knowledge base Q&A','Answer generation','You are an enterprise knowledge base assistant. Answer the user in English using only the sources below.\nIf the sources do not answer the question, reply \"No relevant content was found in the knowledge base.\"\n\nSources:\n{context}\n\nUser question: {question}','context,question','Yes','Main QA Prompt, requiring the model to answer based on the provided materials without deviating.','2026-09-03 21:09:50','2026-09-03 21:09:50');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (2,'QUERY_REWRITE','Multi-query expansion','Query rewrite','Rewrite the user question as {count} search queries with the same meaning, varying the wording and using relevant synonyms.\nReturn only the queries, one per line, without numbering.\n\nUser question: {question}','count,question','Yes','Used for query expansion before multi-path retrieval.','2026-09-03 21:09:50','2026-09-03 21:09:50');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (3,'CONTEXT_GRADE','Context relevance grading','Agentic RAG','Decide whether the sources below can help answer the user question.\nReturn exactly \"Relevant\" or \"Irrelevant\".\n\nSources:\n{context}\n\nUser question: {question}','context,question','Yes','Used for nodes in LangGraph to determine if re-retrieval is needed.','2026-09-03 21:09:50','2026-09-03 21:09:50');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (4,'HALLUCINATION_CHECK','Answer grounding check','Agentic RAG','Decide whether the sources fully support the answer below.\nReturn exactly \"Supported\" or \"Unsupported\".\n\nSources:\n{context}\n\nAnswer:\n{answer}','context,answer','Yes','Post-generation verification, trigger re-generation if unsupported.','2026-09-03 21:09:50','2026-09-03 21:09:50');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (5,'EVAL_CASE_GEN','Evaluation case generation','Dataset construction','Generate {count} question-and-answer pairs in English from the chunks below to evaluate knowledge base answers.\n\nRequirements:\n1. Write specific questions. Each answer must come directly from a single chunk.\n2. Include the number of the source chunk for each pair.\n3. Put only the answer in ground_truth, without explanation or repetition of the question.\n\nReturn a JSON array with these three fields in each object:\n  question       Question\n  ground_truth   Reference answer\n  source_index   Numeric source chunk index from the [Chunk N] labels below\n\nExample:\n[{\"question\": \"How long is the power adapter warranty?\", \"ground_truth\": \"12 months\", \"source_index\": 2}]\n\nChunks:\n{context}','count,context','Yes','Generate evaluation cases based on document fragments, requiring to indicate the source fragment number, for Context Recall as reference','2026-09-03 21:09:50','2026-09-06 23:57:23');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (6,'COREFERENCE_RESOLVE','Conversational coreference resolution','Query rewrite','Rewrite the most recent user message as a complete, standalone question using the conversation history below.\nReturn only the rewritten question.\n\nConversation history:\n{history}\n\nLatest user message: {question}','history,question','Yes','Complete referential questions like \"What about it?\" into full questions in multi-turn dialogues.','2026-09-03 21:09:50','2026-09-03 21:09:50');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (7,'HYDE_ANSWER','HyDE hypothetical answer','Query rewrite','Write a hypothetical answer to the following question in the formal style of company documentation.\nUse wording and sentence structure typical of formal documentation. This is a hypothetical answer.\nReturn only that paragraph and keep it under 150 words.\n\nQuestion: {question}','question','Yes','First generate a fake answer, then use it to retrieve; the closer the semantic space between answers, the better.','2026-09-03 21:09:50','2026-09-03 21:09:50');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (8,'EVAL_SPLIT_STATEMENTS','Evaluation statement splitting','Efficiency Evaluation','Split the text below into standalone statements, each expressing one fact.\nReturn only the statements, one per line, without numbering.\n\nText:\n{text}','text','Yes','Before calculating context recall and fidelity, split the text into individual, assessable statements.','2026-09-03 21:09:50','2026-09-03 21:09:50');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (9,'EVAL_JUDGE_SUPPORT','Evaluation support check','Efficiency Evaluation','For each statement, decide whether it follows from the sources below.\nIn statement order, return only \"Yes\" or \"No\", one per line, without numbering.\n\nSources:\n{context}\n\nStatements:\n{statements}','context,statements','Yes','Judge multiple statements at once, saving many model calls compared to individual calls.','2026-09-03 21:09:50','2026-09-03 21:09:50');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (10,'EVAL_JUDGE_RELEVANCE','Evaluation relevance check','Efficiency Evaluation','For each source below, decide whether it helps answer the question.\nIn source order, return only \"Yes\" or \"No\", one per line, without numbering.\n\nQuestion: {question}\n\nSources:\n{contexts}','question,contexts','Yes','Used for context precision, determine if the retrieved fragments are useful.','2026-09-03 21:09:50','2026-09-03 21:09:50');
INSERT INTO `prompt_template` (`id`, `code`, `name`, `scene`, `content`, `variables`, `enabled`, `remark`, `create_time`, `update_time`) VALUES (11,'EVAL_REVERSE_QUESTION','Evaluation question reconstruction','Efficiency Evaluation','Read the answer below and infer the question it most likely answers.\nReturn only that question.\n\nAnswer:\n{answer}','answer','Yes','Used for answer relevance, the closer the inferred question is to the original question, the more relevant the answer.','2026-09-03 21:09:50','2026-09-03 21:09:50');
INSERT INTO `qa_app` (`id`, `name`, `app_code`, `description`, `avatar`, `chat_model_id`, `retrieval_strategy_id`, `prompt_code`, `agent_enabled`, `max_history`, `empty_answer`, `share_enabled`, `status`, `create_user_id`, `create_time`, `update_time`) VALUES (182,'Product Technical Assistant','c6807d313cbb4104','Focused on pre-sales and field engineers, answering specifications, interfaces, fault codes, firmware upgrades, and warranty and repair policies for GTE series products.',NULL,1,2,'RAG_ANSWER','No',6,'No relevant content was found in the knowledge base.','No','Active',1,'2026-09-04 03:41:09','2026-09-04 11:42:36');
INSERT INTO `qa_app` (`id`, `name`, `app_code`, `description`, `avatar`, `chat_model_id`, `retrieval_strategy_id`, `prompt_code`, `agent_enabled`, `max_history`, `empty_answer`, `share_enabled`, `status`, `create_user_id`, `create_time`, `update_time`) VALUES (183,'Company Policy Q&A','3767c6cd09c94651','Focused on all employees, answering questions about attendance leave, business trip reimbursement, information security, and other policy terms.',NULL,1,3,'RAG_ANSWER','No',8,'No relevant clauses were found in the current system. Please contact the Human Resources Department for confirmation.','No','Active',1,'2026-09-04 03:41:09','2026-09-04 03:41:09');
INSERT INTO `qa_app` (`id`, `name`, `app_code`, `description`, `avatar`, `chat_model_id`, `retrieval_strategy_id`, `prompt_code`, `agent_enabled`, `max_history`, `empty_answer`, `share_enabled`, `status`, `create_user_id`, `create_time`, `update_time`) VALUES (184,'After-Sales Support Assistant','733a379af85246a4','Focused on customer service agents and customers, answering questions about warranty, repair, spare parts, and returns, with Agentic routing to decide whether to re-retrieve.',NULL,1,2,'RAG_ANSWER','Yes',6,'This issue is not found in the post-sale knowledge base and can be referred to artificial passenger service 416-555-0147.','No','Active',1,'2026-09-04 03:41:09','2026-11-16 23:04:58');
