INSERT INTO `retrieval_debug_record` (`id`, `kb_id`, `query`, `strategy_ids`, `result_snapshot`, `cost_millis`, `create_user_id`, `create_time`) VALUES (1,208,'I want to ask about your after-sales refund policy','3','[{\"query\": \"I want to ask about your after-sales refund policy\", \"queries\": [\"I want to ask about your after-sales refund policy\", \"What is your after-sales refund policy?\", \"What are the procedures and conditions for after-sales refunds?\", \"If you need to return goods, how is the refund processed?\"], \"strategy_id\": 3, \"strategy_name\": \"Full - Hybrid search with reranking and rewriting\", \"results\": [], \"stages\": [{\"name\": \"Query Rewriting (Multi-Query Expansion)\", \"count\": 4, \"cost_millis\": 897, \"detail\": [\"I want to ask about your after-sales refund policy\", \"What is your after-sales refund policy?\", \"What are the procedures and conditions for after-sales refunds?\", \"If you need to return goods, how is the refund processed?\"]}, {\"name\": \"Vector search\", \"count\": 40, \"cost_millis\": 1802}, {\"name\": \"BM25 search\", \"count\": 25, \"cost_millis\": 214}, {\"name\": \"RRF fusion\", \"count\": 10, \"cost_millis\": 0}, {\"name\": \"Rerank\", \"count\": \"10 → 4\", \"cost_millis\": 1803}, {\"name\": \"Parent chunk expansion\", \"count\": \"4 → 4\", \"cost_millis\": 0}, {\"name\": \"Threshold Filtering (>= 0.3)\", \"count\": \"4 → 0\", \"cost_millis\": 0}], \"cost_millis\": 4719}]',4720,1,'2026-09-05 14:59:36');
INSERT INTO `retrieval_strategy` (`id`, `name`, `vector_enabled`, `vector_top_k`, `bm25_enabled`, `bm25_top_k`, `rrf_k`, `rerank_enabled`, `rerank_model_id`, `rerank_top_n`, `query_rewrite_enabled`, `rewrite_type`, `multi_query_count`, `parent_recall_enabled`, `vector_score_threshold`, `rerank_score_threshold`, `metadata_filter`, `is_default`, `remark`, `create_time`, `update_time`) VALUES (1,'Baseline - Vector search only','Yes',5,'No',0,60,'No',NULL,3,'No',NULL,3,'No',0.300,NULL,NULL,'Yes',NULL,'2026-09-03 21:09:50','2026-09-07 02:19:18');
INSERT INTO `retrieval_strategy` (`id`, `name`, `vector_enabled`, `vector_top_k`, `bm25_enabled`, `bm25_top_k`, `rrf_k`, `rerank_enabled`, `rerank_model_id`, `rerank_top_n`, `query_rewrite_enabled`, `rewrite_type`, `multi_query_count`, `parent_recall_enabled`, `vector_score_threshold`, `rerank_score_threshold`, `metadata_filter`, `is_default`, `remark`, `create_time`, `update_time`) VALUES (2,'Advanced - Hybrid search','Yes',8,'Yes',8,60,'No',NULL,3,'No',NULL,3,'No',0.300,NULL,NULL,'No','Vector plus BM25 dual-path retrieval followed by RRF fusion, to solve the problem of retrieving proper nouns.','2026-09-03 21:09:50','2026-09-06 14:07:46');
INSERT INTO `retrieval_strategy` (`id`, `name`, `vector_enabled`, `vector_top_k`, `bm25_enabled`, `bm25_top_k`, `rrf_k`, `rerank_enabled`, `rerank_model_id`, `rerank_top_n`, `query_rewrite_enabled`, `rewrite_type`, `multi_query_count`, `parent_recall_enabled`, `vector_score_threshold`, `rerank_score_threshold`, `metadata_filter`, `is_default`, `remark`, `create_time`, `update_time`) VALUES (3,'Full - Hybrid search with reranking and rewriting','Yes',10,'Yes',10,60,'Yes',4,4,'Yes','Multi-query expansion',3,'Yes',0.300,0.250,NULL,'No','Local hybrid retrieval with Ollama reranking, query rewriting, and parent chunk expansion.','2026-09-03 21:09:50','2026-09-06 14:07:46');
